INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C1','kor',2,2,'u1',1,'시를 낭송하며 장면 떠올리기 — 시의 느낌이나 분위기를 살려 노래하듯이 소리 내어 읽는 낭송의 뜻을 알고, 서로 번갈아 가며·흉내 내는 말을 함께 낭송하며 시의 말에서 떠오르는 장면을 말하기',ARRAY['2국05-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C2','kor',2,2,'u1',1,'이야기를 소개하고 궁금한 점 묻기 — 좋아하는 이야기를 제목·좋아하는 까닭·기억에 남는 부분·관련 경험을 넣어 소개하고, 친구의 소개를 듣고 언제·누가·그다음에 어떤 일이 일어났는지 묻기, 병풍책·삼면책으로 소개하기',ARRAY['2국01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C3','kor',2,2,'u1',3,'세 가지 방법으로 시의 장면 상상하기 — 시의 내용을 생각하며·인상 깊은 표현을 생각하며·자신의 경험과 비교하며 장면을 상상하고, 정답은 없지만 시어·시구·상황·분위기를 근거로 상상하기',ARRAY['2국05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C4','kor',2,2,'u1',3,'시의 내용 파악하기 — 「헬리콥터」·「짜장 요일」·「우산」·「서로」에서 누가·언제·무엇을·왜를 묻고 답하며, 흉내 내는 말과 빗대어 나타낸 말(헬리콥터가 된 아이들·짜장 수염)을 글자 그대로가 아니라 장면으로 이해하기',ARRAY['2국05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C5','kor',2,2,'u1',5,'시에 대한 생각이나 느낌 나누기 — 시의 장면·표현·비슷한 경험과 이어 생각이나 느낌을 말하고, 친구와 비슷한 점과 다른 점을 견주며 다양한 반응을 존중하기(반응 중심 학습)',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C6','kor',2,2,'u1',7,'이야기의 내용과 차례 파악하기 — 「할머니와 하얀 집」·「엉뚱한 수리점」에서 인물·일어난 일·장소를 확인하고, 일이 일어난 차례대로 장면을 늘어놓기',ARRAY['2국05-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C7','kor',2,2,'u1',7,'상황·말·행동을 근거로 인물의 마음 상상하기 — 이야기의 상황과 인물의 말이나 행동을 근거로 인물의 마음(불안·놀람·즐거움 등)을 짐작하고, 이야기가 흐르며 마음이 바뀌는 것을 알기',ARRAY['2국05-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C8','kor',2,2,'u1',9,'이야기에 대한 생각이나 느낌 나누기 — 인물의 모습·인물이 겪은 일·자신의 경험에서 생각이나 느낌을 떠올리고, 제목과 인물에 대한 생각을 이야기 내용과 이어 말하거나 인물에게 하고 싶은 말·답장으로 표현하기',ARRAY['2국03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u1-C9','kor',2,2,'u1',9,'낱말의 뜻과 소리 바르게 알기 — 도무지·곰곰이·멀쩡한처럼 문맥에 맞는 낱말 고르기, 이중 모음 ㅒ(얘기·걔)와 ㅖ(예의·예방)의 입 모양과 쓰임 구별하기(기초 다지기)',ARRAY['2국05-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X01','kor',2,'u1',ARRAY['K2-2-u1-C1']::text[],'낭송을 눈으로만 읽기·외우기·빨리 읽기로 여기거나, 여러 가지 낭송 방법을 구별하지 못한다','시 한 줄을 노래하듯 읽어 주고, 눈으로만 읽을 때와 무엇이 다른지 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X02','kor',2,'u1',ARRAY['K2-2-u1-C1','K2-2-u1-C3']::text[],'시나 이야기의 말과 상관없는 장면을 떠올린다(근거 없는 상상)','「시의 어느 말에서 그 장면이 떠올랐어?」 — 말을 짚지 못하면 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X03','kor',2,'u1',ARRAY['K2-2-u1-C3']::text[],'장면을 상상하는 세 가지 방법(내용·인상 깊은 표현·자신의 경험)을 섞거나, 글자 수 세기처럼 상관없는 것을 방법으로 고른다','「저도 ~한 적이 있어요」면 경험, 「○○라는 말이」면 표현, 그 밖에 줄거리면 내용 — 세 칸 상자에 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X04','kor',2,'u1',ARRAY['K2-2-u1-C3','K2-2-u1-C5']::text[],'상상이나 생각·느낌에 정답이 하나뿐이라고 여기거나, 친구와 다르면 틀렸다고 여긴다','같은 시를 읽은 친구 셋의 그림을 나란히 보고 「모두 시의 말에서 나왔나?」만 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X05','kor',2,'u1',ARRAY['K2-2-u1-C4']::text[],'시의 내용(누가·언제·무엇을·왜)을 잘못 읽거나 뒤섞는다','「그 내용이 몇째 연에 있나요?」 교과서를 짚게 하고 그 줄만 다시 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X06','kor',2,'u1',ARRAY['K2-2-u1-C4','K2-2-u1-C5']::text[],'빗대어 나타낸 말이나 흉내 내는 말을 글자 그대로 받아들인다(진짜 헬리콥터·진짜 수염·진짜 냉장고)','「정말 그랬을까, 그렇게 보였을까?」 — 「~처럼」을 넣어 다시 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X07','kor',2,'u1',ARRAY['K2-2-u1-C5','K2-2-u1-C8']::text[],'생각이나 느낌을 작품과 상관없는 말(오늘 한 일·글자 수·건물 층수)로 말한다','「그 말이 시(이야기)의 어느 장면과 이어져?」 — 이어지지 않으면 다시 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X08','kor',2,'u1',ARRAY['K2-2-u1-C5','K2-2-u1-C8']::text[],'비슷한 경험을 고를 때 작품과 닮은 점이 없는 경험을 고른다','작품의 장면 한 가지(얼굴에 묻은 짜장)를 먼저 말하고 「그것과 닮은 일」을 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X09','kor',2,'u1',ARRAY['K2-2-u1-C2']::text[],'이야기를 소개할 때 제목·까닭·기억에 남는 부분 대신 가격·무게 같은 것을 넣거나, 이야기와 상관없는 것을 묻는다','「이 말을 들으면 친구가 그 이야기를 읽고 싶어질까?」 한 가지 물음으로 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X10','kor',2,'u1',ARRAY['K2-2-u1-C6']::text[],'이야기에서 일이 일어난 차례를 뒤섞는다','장면 카드를 처음·가운데·끝 세 칸에 놓고 「그다음에?」를 이어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X11','kor',2,'u1',ARRAY['K2-2-u1-C6']::text[],'인물이 한 말·행동이나 일어난 일을 잘못 읽거나 다른 인물 것과 엇갈린다','「누가 한 말이야?」 — 교과서에서 그 말 앞뒤를 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X12','kor',2,'u1',ARRAY['K2-2-u1-C7']::text[],'상황·말·행동을 근거로 하지 않고 자기 기분대로 인물의 마음을 짐작한다','「할머니가 무엇을 했지? 그래서 마음이?」 행동 → 마음 순서로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X13','kor',2,'u1',ARRAY['K2-2-u1-C7']::text[],'인물의 마음이 이야기 내내 그대로라고 여겨 마음이 바뀌는 것을 보지 못한다','처음·가운데·끝 장면마다 얼굴 그림을 그려 마음 바뀜 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X14','kor',2,'u1',ARRAY['K2-2-u1-C8']::text[],'제목이나 인물에 대한 생각을 이야기 내용과 이어 말하지 못하고 엉뚱하게 말한다','「소이는 물건을 볼 때 무엇을 찾았지?」 — 인물이 한 일을 하나 들고 생각을 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X15','kor',2,'u1',ARRAY['K2-2-u1-C9']::text[],'낱말의 뜻을 문맥과 다르게 고른다(도무지·곰곰이·멀쩡한)','고른 낱말을 문장에 넣어 소리 내어 읽고 말이 되는지 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X16','kor',2,'u1',ARRAY['K2-2-u1-C9']::text[],'ㅒ와 ㅖ, ㅐ와 ㅔ를 헷갈려 쓰거나 읽는다(얘기→예기, 예의→얘의)','거울 앞에서 ㅣ→ㅐ(턱이 조금 더 내려감), ㅣ→ㅔ 입 모양을 번갈아 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u1-X17','kor',2,'u1',ARRAY['K2-2-u1-C2']::text[],'병풍책·삼면책을 만드는 차례나 표지·안쪽에 들어갈 것을 헷갈린다','34쪽 그림 ①②③을 손가락으로 짚으며 순서대로 말한 뒤 만들기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#1','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C1',1,'mc','auto','『국어』 7쪽 생각 열기 — 여자아이는 「콩쥐팥쥐」를 읽고 어떤 장면을 떠올렸나요?',ARRAY['K2-2-u1-X02']::text[],false,'{"seq":1,"concept":"K2-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 7쪽 생각 열기 — 여자아이는 「콩쥐팥쥐」를 읽고 어떤 장면을 떠올렸나요?","options":[{"t":"두꺼비가 물독의 깨진 부분을 막아 주는 장면","correct":true},{"t":"소가 밭을 가는 장면","mis":"K2-2-u1-X02"},{"t":"콩쥐가 학교에 가는 장면","mis":"K2-2-u1-X02"}],"explanation":["두꺼비가 물독을 막아 주는 장면이에요.","읽은 글이 머릿속 그림이 되었어요.","지도서 58쪽이에요."],"asset":{"type":"speech","turns":[{"who":"이야기 속 두꺼비","text":"콩쥐야, 내가 물독의 깨진 부분을 막아 줄 테니 걱정하지 마."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#2','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C7',1,'mc','auto','두꺼비가 물독의 깨진 부분을 막아 주었을 때 콩쥐의 마음은 어떠했을까요?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":2,"concept":"K2-2-u1-C7","difficulty":1,"kind":"mc","stem":"두꺼비가 물독의 깨진 부분을 막아 주었을 때 콩쥐의 마음은 어떠했을까요?","options":[{"t":"고마웠을 것 같아요","correct":true},{"t":"귀찮았을 것 같아요","mis":"K2-2-u1-X12"},{"t":"화가 났을 것 같아요","mis":"K2-2-u1-X12"}],"explanation":["걱정하던 콩쥐를 도와주었어요.","그래서 고마웠을 거예요.","지도서 58쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"이야기 속 두꺼비","text":"콩쥐야, 내가 물독의 깨진 부분을 막아 줄 테니 걱정하지 마."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#3','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C1',1,'mc','auto','시의 느낌이나 분위기를 살려 노래하듯이 시를 소리 내어 읽는 것을 무엇이라고 하나요?',ARRAY['K2-2-u1-X01']::text[],false,'{"seq":3,"concept":"K2-2-u1-C1","difficulty":1,"kind":"mc","stem":"시의 느낌이나 분위기를 살려 노래하듯이 시를 소리 내어 읽는 것을 무엇이라고 하나요?","options":[{"t":"낭송","correct":true},{"t":"받아쓰기","mis":"K2-2-u1-X01"},{"t":"눈으로 읽기","mis":"K2-2-u1-X01"}],"explanation":["낭송이에요.","노래하듯 소리 내어 읽어요.","『국어』 8쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#4','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C2',1,'mc','auto','『국어』 9쪽 — 친구가 소개한 책의 제목은 무엇인가요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":4,"concept":"K2-2-u1-C2","difficulty":1,"kind":"mc","stem":"『국어』 9쪽 — 친구가 소개한 책의 제목은 무엇인가요?","options":[{"t":"『치과 의사 드소토 선생님』","correct":true},{"t":"『콩쥐팥쥐』","mis":"K2-2-u1-X11"},{"t":"『떡볶이』","mis":"K2-2-u1-X11"}],"explanation":["『치과 의사 드소토 선생님』이에요.","제목을 먼저 말했어요.","9쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"얼마 전에 『치과 의사 드소토 선생님』이라는 책을 읽었어. 지혜롭게 여우를 골탕 먹이는 드소토 선생님의 이야기가 정말 재미있었어."},{"who":"친구 2","text":"드소토 선생님은 쥐라서 몸집이 작은데 몸집이 큰 동물들의 이빨을 어떻게 치료해?"},{"who":"친구 1","text":"드소토 선생님은 사다리를 타고 올라가서 몸집이 큰 동물들의 이빨을 치료해 주었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#5','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C1',2,'mc','auto','『국어』 8쪽 (2) — 「떡볶이」를 읽고 떠오르는 장면으로 알맞은 것은?',ARRAY['K2-2-u1-X02']::text[],false,'{"seq":5,"concept":"K2-2-u1-C1","difficulty":2,"kind":"mc","stem":"『국어』 8쪽 (2) — 「떡볶이」를 읽고 떠오르는 장면으로 알맞은 것은?","options":[{"t":"매콤한 떡볶이를 먹으면서 땀을 흘리는 아이의 모습","correct":true},{"t":"눈사람을 만드는 아이의 모습","mis":"K2-2-u1-X02"},{"t":"침대에서 잠을 자는 아이의 모습","mis":"K2-2-u1-X02"}],"explanation":["시의 말에서 나온 장면이에요.","떡볶이와 상관없는 장면은 아니에요.","8쪽 말풍선이에요."],"asset":{"type":"scene","icon":"🌶️🧒🧒","text":"『국어』 8쪽 「떡볶이」(정두리) — 단짝 친구와 달콤하고 매콤한 떡볶이를 먹고 싶어 하는 마음을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#6','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C2',2,'match','auto','친구가 이야기를 소개한 말을 보고, 소개한 것과 그 말을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-2-u1-C2","difficulty":2,"kind":"match","stem":"친구가 이야기를 소개한 말을 보고, 소개한 것과 그 말을 이어 보세요.","pairs":[{"l":"제목","r":"『치과 의사 드소토 선생님』"},{"l":"좋아하는 까닭","r":"지혜롭게 여우를 골탕 먹이는 이야기가 재미있었어"},{"l":"궁금한 점","r":"몸집이 큰 동물들의 이빨을 어떻게 치료해?"}],"mis":"K2-2-u1-X09","explanation":["제목·까닭·궁금한 점을 이어요.","소개할 때 넣으면 좋은 것이에요.","지도서 59쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"얼마 전에 『치과 의사 드소토 선생님』이라는 책을 읽었어. 지혜롭게 여우를 골탕 먹이는 드소토 선생님의 이야기가 정말 재미있었어."},{"who":"친구 2","text":"드소토 선생님은 쥐라서 몸집이 작은데 몸집이 큰 동물들의 이빨을 어떻게 치료해?"},{"who":"친구 1","text":"드소토 선생님은 사다리를 타고 올라가서 몸집이 큰 동물들의 이빨을 치료해 주었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#7','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C2',2,'mc','auto','『국어』 9쪽 3번 — 친구의 궁금한 점에 대한 대답은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":7,"concept":"K2-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어』 9쪽 3번 — 친구의 궁금한 점에 대한 대답은?","options":[{"t":"사다리를 타고 올라가서 이빨을 치료해 주었어","correct":true},{"t":"여우에게 부탁했어","mis":"K2-2-u1-X11"},{"t":"몸집이 커지는 약을 먹었어","mis":"K2-2-u1-X11"}],"explanation":["사다리를 타고 올라갔어요.","말풍선을 다시 읽어요.","9쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"얼마 전에 『치과 의사 드소토 선생님』이라는 책을 읽었어. 지혜롭게 여우를 골탕 먹이는 드소토 선생님의 이야기가 정말 재미있었어."},{"who":"친구 2","text":"드소토 선생님은 쥐라서 몸집이 작은데 몸집이 큰 동물들의 이빨을 어떻게 치료해?"},{"who":"친구 1","text":"드소토 선생님은 사다리를 타고 올라가서 몸집이 큰 동물들의 이빨을 치료해 주었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#8','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C1',2,'ox','auto','시를 읽고 떠오르는 장면은 모든 사람이 똑같아야 해요.',ARRAY['K2-2-u1-X04']::text[],false,'{"seq":8,"concept":"K2-2-u1-C1","difficulty":2,"kind":"ox","stem":"시를 읽고 떠오르는 장면은 모든 사람이 똑같아야 해요.","answer":"X","reason_options":[{"t":"사람마다 경험이 달라 떠오르는 장면이 다를 수 있으니까","correct":true},{"t":"선생님이 정해 준 장면만 맞으니까","mis":"K2-2-u1-X04"}],"mis":"K2-2-u1-X04","explanation":["반응은 사람마다 달라요.","다른 것이 틀린 것은 아니에요.","지도서 58쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
