INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_basic#10','kor',2,2,'u1','L01','g2_2_kor_u1_L01_basic','lesson_basic','K2-2-u1-C2',3,'mc','auto','친구가 소개하는 이야기를 듣고 궁금한 점을 물을 때 알맞은 질문은?',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":10,"concept":"K2-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구가 소개하는 이야기를 듣고 궁금한 점을 물을 때 알맞은 질문은?","options":[{"t":"그다음에 어떤 일이 일어났어?","correct":true},{"t":"너는 어제 저녁에 무엇을 먹었어?","mis":"K2-2-u1-X09"},{"t":"그 책은 몇 쪽이야?","mis":"K2-2-u1-X09"}],"explanation":["이야기 내용을 물어요.","상관없는 질문은 하지 않아요.","지도서 59쪽 예시 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
