INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#4','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C5',3,'mc','auto','같은 시를 읽고 친구와 떠오른 장면이 다를 때 알맞은 생각은?',ARRAY['K2-2-u1-X04']::text[],false,'{"seq":4,"concept":"K2-2-u1-C5","difficulty":3,"kind":"mc","stem":"같은 시를 읽고 친구와 떠오른 장면이 다를 때 알맞은 생각은?","options":[{"t":"사람마다 작품에 대한 반응이 다를 수 있어요","correct":true},{"t":"친구나 내가 틀렸어요","mis":"K2-2-u1-X04"},{"t":"다시는 말하지 않아요","mis":"K2-2-u1-X04"}],"explanation":["반응은 다를 수 있어요.","나누면 감상이 넓어져요.","지도서 58쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#5','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C2',3,'mc','auto','친구가 소개한 이야기에 흥미가 생겼어요. 무엇을 하면 좋을까요?',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":5,"concept":"K2-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구가 소개한 이야기에 흥미가 생겼어요. 무엇을 하면 좋을까요?","options":[{"t":"도서관이나 집에서 그 이야기를 찾아 읽어요","correct":true},{"t":"친구에게 줄거리를 다 외우게 해요","mis":"K2-2-u1-X09"},{"t":"그 책은 읽지 않아요","mis":"K2-2-u1-X09"}],"explanation":["찾아 읽으면 독서로 이어져요.","소개의 좋은 점이에요.","지도서 58쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#6','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C1',3,'mc','auto','「떡볶이」를 읽은 친구들이 장면을 말했어요. 시의 말에서 나온 장면을 말한 친구는?',ARRAY['K2-2-u1-X02']::text[],false,'{"seq":6,"concept":"K2-2-u1-C1","difficulty":3,"kind":"mc","stem":"「떡볶이」를 읽은 친구들이 장면을 말했어요. 시의 말에서 나온 장면을 말한 친구는?","options":[{"t":"단짝과 함께 매콤한 떡볶이를 먹는 모습이 떠올랐어","correct":true},{"t":"혼자 수영장에서 노는 모습이 떠올랐어","mis":"K2-2-u1-X02"},{"t":"겨울에 눈사람을 만드는 모습이 떠올랐어","mis":"K2-2-u1-X02"}],"explanation":["시의 말을 근거로 떠올렸어요.","떡볶이와 단짝이 나와요.","8쪽이에요."],"asset":{"type":"scene","icon":"🌶️🧒🧒","text":"『국어』 8쪽 「떡볶이」(정두리) — 단짝 친구와 달콤하고 매콤한 떡볶이를 먹고 싶어 하는 마음을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#7','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C2',3,'mc','auto','「몸집이 큰 동물들의 이빨을 어떻게 치료해?」는 이야기의 무엇을 궁금해한 질문인가요?',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":7,"concept":"K2-2-u1-C2","difficulty":3,"kind":"mc","stem":"「몸집이 큰 동물들의 이빨을 어떻게 치료해?」는 이야기의 무엇을 궁금해한 질문인가요?","options":[{"t":"인물이 어떻게 행동했는지","correct":true},{"t":"책이 얼마인지","mis":"K2-2-u1-X09"},{"t":"친구가 언제 태어났는지","mis":"K2-2-u1-X09"}],"explanation":["인물의 행동을 물었어요.","이야기 안의 궁금한 점이에요.","9쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"드소토 선생님은 몸집이 작은데 어떻게 큰 동물을 치료해?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#8','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C2',4,'sa','auto','『국어』 9쪽 — 드소토 선생님은 무엇을 타고 올라가서 큰 동물들의 이빨을 치료했나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u1-C2","difficulty":4,"kind":"sa","stem":"『국어』 9쪽 — 드소토 선생님은 무엇을 타고 올라가서 큰 동물들의 이빨을 치료했나요? 세 글자로 쓰세요.","answer":["사다리"],"explanation":["사다리예요.","말풍선을 다시 읽어요.","9쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"얼마 전에 『치과 의사 드소토 선생님』이라는 책을 읽었어. 지혜롭게 여우를 골탕 먹이는 드소토 선생님의 이야기가 정말 재미있었어."},{"who":"친구 2","text":"드소토 선생님은 쥐라서 몸집이 작은데 몸집이 큰 동물들의 이빨을 어떻게 치료해?"},{"who":"친구 1","text":"드소토 선생님은 사다리를 타고 올라가서 몸집이 큰 동물들의 이빨을 치료해 주었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#9','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C2',4,'essay','teacher','좋아하는 이야기를 하나 골라 제목·좋아하는 까닭·기억에 남는 부분을 넣어 소개하는 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u1-C2","difficulty":4,"kind":"essay","stem":"좋아하는 이야기를 하나 골라 제목·좋아하는 까닭·기억에 남는 부분을 넣어 소개하는 말을 쓰세요.","answer_guide":{"answer":"예: 내가 좋아하는 이야기는 『콩쥐팥쥐』야. 두꺼비가 물독을 막아 주는 장면이 기억에 남아. 어려울 때 도와주는 친구가 있어서 좋았어. — 세 가지가 들어 있으면 맞아요.","scoring_points":["제목을 썼는가","좋아하는 까닭을 썼는가","기억에 남는 부분을 썼는가"]},"explanation":["세 가지를 넣어요.","친구가 읽고 싶어지게 써요.","지도서 59쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L01_challenge#10','kor',2,2,'u1','L01','g2_2_kor_u1_L01_challenge','lesson_challenge','K2-2-u1-C1',4,'essay','teacher','『국어』 8쪽 「떡볶이」를 낭송하고, 떠오르는 장면을 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u1-C1","difficulty":4,"kind":"essay","stem":"『국어』 8쪽 「떡볶이」를 낭송하고, 떠오르는 장면을 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 단짝 친구와 마주 앉아 매콤한 떡볶이를 호호 불며 먹는 모습이 떠올랐어요. — 시의 말과 이어진 장면이면 맞아요.","scoring_points":["시의 말과 이어진 장면인가","누가 무엇을 하는지 드러나는가","완결된 문장인가"]},"explanation":["시의 말을 근거로.","장면이 보이게 써요.","8쪽이에요."],"asset":{"type":"scene","icon":"🌶️🧒🧒","text":"『국어』 8쪽 「떡볶이」(정두리) — 단짝 친구와 달콤하고 매콤한 떡볶이를 먹고 싶어 하는 마음을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#1','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C4',1,'mc','auto','「헬리콥터」 — 아이들이 신난 까닭은 무엇일까요?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":1,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「헬리콥터」 — 아이들이 신난 까닭은 무엇일까요?","options":[{"t":"학교가 끝났기 때문이에요","correct":true},{"t":"생일 잔치를 하기 때문이에요","mis":"K2-2-u1-X05"},{"t":"비가 그쳤기 때문이에요","mis":"K2-2-u1-X05"}],"explanation":["학교가 끝나서 신났어요.","11쪽 2번 (1) 예시 답안이에요.","시의 첫 부분을 떠올려요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#2','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C4',1,'mc','auto','「헬리콥터」에서 아이들이 머리 위에서 돌린 물건은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":2,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「헬리콥터」에서 아이들이 머리 위에서 돌린 물건은?","options":[{"t":"신발주머니 가방","correct":true},{"t":"우산","mis":"K2-2-u1-X05"},{"t":"줄넘기 줄","mis":"K2-2-u1-X05"}],"explanation":["신발주머니 가방이에요.","그 모습이 헬리콥터 날개 같아요.","지도서 61쪽이에요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#3','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C3',1,'mc','auto','『국어』 11쪽 2번 (2) — 헬리콥터가 된 아이들의 모습을 흉내 내는 말은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":3,"concept":"K2-2-u1-C3","difficulty":1,"kind":"mc","stem":"『국어』 11쪽 2번 (2) — 헬리콥터가 된 아이들의 모습을 흉내 내는 말은?","options":[{"t":"헬리콥터 소리 「두두두두두」","correct":true},{"t":"강아지 소리 「멍멍」","mis":"K2-2-u1-X05"},{"t":"종소리 「딩동댕」","mis":"K2-2-u1-X05"}],"explanation":["헬리콥터 소리를 흉내 냈어요.","흉내 내는 말이 장면을 실감 나게 해요.","11쪽 예시 답안이에요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#4','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C3',1,'mc','auto','시의 장면을 상상하는 방법에 들어가는 것은?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":4,"concept":"K2-2-u1-C3","difficulty":1,"kind":"mc","stem":"시의 장면을 상상하는 방법에 들어가는 것은?","options":[{"t":"자신의 경험과 비교하며 장면 상상하기","correct":true},{"t":"글자 수를 세며 장면 상상하기","mis":"K2-2-u1-X03"},{"t":"제목만 외우며 장면 상상하기","mis":"K2-2-u1-X03"}],"explanation":["내용·표현·경험, 세 가지예요.","글자 수는 상관없어요.","『국어』 12쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#5','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C4',2,'mc','auto','시에서 무엇을 보고 「난다」라고 표현했을까요?',ARRAY['K2-2-u1-X06','K2-2-u1-X05']::text[],false,'{"seq":5,"concept":"K2-2-u1-C4","difficulty":2,"kind":"mc","stem":"시에서 무엇을 보고 「난다」라고 표현했을까요?","options":[{"t":"신이 나서 발이 땅에서 떠오를 듯 달리는 아이들","correct":true},{"t":"하늘을 나는 진짜 헬리콥터","mis":"K2-2-u1-X06"},{"t":"나뭇가지에 앉은 새","mis":"K2-2-u1-X05"}],"explanation":["진짜로 나는 것이 아니에요.","날아오를 듯 신난 아이들이에요.","지도서 61쪽이에요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#6','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C3',2,'match','auto','『국어』 12쪽 3번 — 상상하는 방법과 상상한 장면을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-2-u1-C3","difficulty":2,"kind":"match","stem":"『국어』 12쪽 3번 — 상상하는 방법과 상상한 장면을 이어 보세요.","pairs":[{"l":"시의 내용을 생각하며","r":"학교가 끝나자 신발주머니를 돌리며 집으로 가는 아이들"},{"l":"인상 깊은 표현을 생각하며","r":"헬리콥터 소리를 흉내 낸 말에서 날듯이 기뻐하는 아이들"},{"l":"자신의 경험과 비교하며","r":"방학식 날 신나게 집으로 달려가던 내 모습"}],"mis":"K2-2-u1-X03","explanation":["세 가지 길로 상상했어요.","경험은 「내 모습」이에요.","12쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#7','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C3',2,'mc','auto','「방학식 날 학교 끝나고 신나게 집으로 달려가던 내 모습이 떠올랐어.」는 어떤 방법으로 상상한 것인가요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":7,"concept":"K2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「방학식 날 학교 끝나고 신나게 집으로 달려가던 내 모습이 떠올랐어.」는 어떤 방법으로 상상한 것인가요?","options":[{"t":"자신의 경험과 비교하며","correct":true},{"t":"인상 깊은 표현을 생각하며","mis":"K2-2-u1-X03"},{"t":"시의 내용을 생각하며","mis":"K2-2-u1-X03"}],"explanation":["「내 모습」은 나의 경험이에요.","경험과 견주었어요.","12쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#8','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C3',2,'mc','auto','「헬리콥터 소리를 흉내 낸 말 덕분에 헬리콥터가 된 아이들이 실감 나게 떠올라.」는 어떤 방법으로 상상한 것인가요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":8,"concept":"K2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「헬리콥터 소리를 흉내 낸 말 덕분에 헬리콥터가 된 아이들이 실감 나게 떠올라.」는 어떤 방법으로 상상한 것인가요?","options":[{"t":"인상 깊은 표현을 생각하며","correct":true},{"t":"자신의 경험과 비교하며","mis":"K2-2-u1-X03"},{"t":"시의 내용을 생각하며","mis":"K2-2-u1-X03"}],"explanation":["흉내 내는 말이라는 표현에 주목했어요.","표현이 실마리예요.","지도서 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#9','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C3',2,'ox','auto','시의 장면을 상상할 때에는 시에 나온 말과 상관없이 마음대로 떠올려도 돼요.',ARRAY['K2-2-u1-X02']::text[],false,'{"seq":9,"concept":"K2-2-u1-C3","difficulty":2,"kind":"ox","stem":"시의 장면을 상상할 때에는 시에 나온 말과 상관없이 마음대로 떠올려도 돼요.","answer":"X","reason_options":[{"t":"정답은 없지만 시에 나온 말과 상황을 근거로 상상해야 하니까","correct":true},{"t":"상상에는 아무 근거도 필요 없으니까","mis":"K2-2-u1-X02"}],"mis":"K2-2-u1-X02","explanation":["근거는 시의 말이에요.","정답은 없지만 근거는 있어요.","지도서 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_basic#10','kor',2,2,'u1','L03','g2_2_kor_u1_L03_basic','lesson_basic','K2-2-u1-C1',3,'mc','auto','선생님이 「방귀 한 개」를 낭송해 주셨어요. 시의 말과 어울리는 장면은?',ARRAY['K2-2-u1-X02']::text[],false,'{"seq":10,"concept":"K2-2-u1-C1","difficulty":3,"kind":"mc","stem":"선생님이 「방귀 한 개」를 낭송해 주셨어요. 시의 말과 어울리는 장면은?","options":[{"t":"몸에서 나온 방귀가 풍선처럼 떠가려다 뽕 터지는 장면","correct":true},{"t":"풍선을 파는 가게 앞 장면","mis":"K2-2-u1-X02"},{"t":"비 오는 운동장 장면","mis":"K2-2-u1-X02"}],"explanation":["방귀를 풍선에 빗댄 시예요.","시의 말과 이어진 장면이에요.","지도서 60쪽이에요."],"asset":{"type":"scene","icon":"💨🎈🧒","text":"지도서 60쪽 「방귀 한 개」(권오삼) — 아침에 몸에서 나온 방귀를 하늘로 떠가고 싶은 오색 풍선에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
