INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#4','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C4',3,'error','auto','한 친구가 「헬리콥터에는 진짜 헬리콥터가 하늘을 나는 장면이 나와.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X06']::text[],false,'{"seq":4,"concept":"K2-2-u1-C4","difficulty":3,"kind":"error","stem":"한 친구가 「헬리콥터에는 진짜 헬리콥터가 하늘을 나는 장면이 나와.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"신난 아이들을 헬리콥터에 빗대었어요 — 진짜 헬리콥터가 아니에요","correct":true,"mis_target":"K2-2-u1-X06"},{"t":"잘 말했어요","mis":"K2-2-u1-X06"},{"t":"비행기라고 해야 해요","mis":"K2-2-u1-X06"}],"explanation":["아이들이 헬리콥터처럼 보였어요.","「~처럼」 넣어 풀어요.","지도서 61쪽이에요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#5','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C3',3,'mc','auto','『국어활동』 8쪽 — 「궁시렁궁시렁 나라」를 읽고 떠올릴 수 있는 장면을 바르게 말한 친구는?',ARRAY['K2-2-u1-X02']::text[],false,'{"seq":5,"concept":"K2-2-u1-C3","difficulty":3,"kind":"mc","stem":"『국어활동』 8쪽 — 「궁시렁궁시렁 나라」를 읽고 떠올릴 수 있는 장면을 바르게 말한 친구는?","options":[{"t":"친구 1 — 잃어버린 귀고리가 침대 밑에 먼지를 뒤집어쓴 채 놓인 장면","correct":true},{"t":"친구 2 — 물건들이 가지런히 정리된 장면","mis":"K2-2-u1-X02"},{"t":"친구 3 — 방 안에 물건이 가득 쌓인 장면","mis":"K2-2-u1-X02"}],"explanation":["시의 내용과 맞는 장면이에요.","침대 밑 잃어버린 물건 이야기예요.","국어활동 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"엄마의 잃어버린 귀고리가 침대 밑에 먼지를 뒤집어쓴 채 놓여 있는 장면이 떠올라."},{"who":"친구 2","text":"침대 밑의 공간에 물건들을 가지런히 정리해 보관하고 있는 장면이 떠올라."},{"who":"친구 3","text":"정리정돈을 제대로 못 해서 물건이 방 안에 가득히 쌓여 있는 장면이 떠올라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#6','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C3',3,'mc','auto','『국어활동』 9쪽 ①은 어떤 방법으로 장면을 상상했나요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":6,"concept":"K2-2-u1-C3","difficulty":3,"kind":"mc","stem":"『국어활동』 9쪽 ①은 어떤 방법으로 장면을 상상했나요?","options":[{"t":"자신의 경험과 비교하며 장면 상상하기","correct":true},{"t":"인상 깊은 표현을 생각하며 장면 상상하기","mis":"K2-2-u1-X03"},{"t":"내용을 떠올리며 장면 상상하기","mis":"K2-2-u1-X03"}],"explanation":["지우개를 잃어버린 내 경험이에요.","「~적이 있어」가 실마리예요.","국어활동 예시 답안이에요."],"asset":{"type":"passage","lines":["① 아끼던 지우개를 잃어버린 줄 알고 새로 샀는데","한참 뒤에 책상 밑에서 다시 찾은 적이 있어.","그때 지우개에 미안한 마음이 들었던 기억이 떠올랐어.","② ‘궁시렁궁시렁’이라는 표현을 보고 물건들이 주인에게 불만을 드러내는 장면을 상상했어.","③ 어두컴컴한 침대 밑에 놓여 있는 연필, 20센티미터 자,","로봇, 엄마 귀고리를 상상했어."],"title":"『국어활동』 9쪽 — 「궁시렁궁시렁 나라」를 읽고 한 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#7','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C3',3,'mc','auto','『국어활동』 9쪽 ②는 어떤 방법으로 장면을 상상했나요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":7,"concept":"K2-2-u1-C3","difficulty":3,"kind":"mc","stem":"『국어활동』 9쪽 ②는 어떤 방법으로 장면을 상상했나요?","options":[{"t":"인상 깊은 표현을 생각하며 장면 상상하기","correct":true},{"t":"자신의 경험과 비교하며 장면 상상하기","mis":"K2-2-u1-X03"},{"t":"내용을 떠올리며 장면 상상하기","mis":"K2-2-u1-X03"}],"explanation":["‘궁시렁궁시렁’이라는 표현이에요.","표현이 실마리예요.","국어활동 예시 답안이에요."],"asset":{"type":"passage","lines":["① 아끼던 지우개를 잃어버린 줄 알고 새로 샀는데","한참 뒤에 책상 밑에서 다시 찾은 적이 있어.","그때 지우개에 미안한 마음이 들었던 기억이 떠올랐어.","② ‘궁시렁궁시렁’이라는 표현을 보고 물건들이 주인에게 불만을 드러내는 장면을 상상했어.","③ 어두컴컴한 침대 밑에 놓여 있는 연필, 20센티미터 자,","로봇, 엄마 귀고리를 상상했어."],"title":"『국어활동』 9쪽 — 「궁시렁궁시렁 나라」를 읽고 한 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#8','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C3',4,'sa','auto','「저도 ~한 적이 있어요」처럼 장면을 상상하는 방법은 「자신의 ( )과 비교하며 장면 상상하기」예요. 빈칸에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u1-C3","difficulty":4,"kind":"sa","stem":"「저도 ~한 적이 있어요」처럼 장면을 상상하는 방법은 「자신의 ( )과 비교하며 장면 상상하기」예요. 빈칸에 들어갈 두 글자를 쓰세요.","answer":["경험"],"explanation":["경험이에요.","나의 일과 견주어요.","12쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#9','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C3',4,'essay','teacher','「헬리콥터」를 읽고 자신의 경험과 비교하며 떠오르는 장면을 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u1-C3","difficulty":4,"kind":"essay","stem":"「헬리콥터」를 읽고 자신의 경험과 비교하며 떠오르는 장면을 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 저도 학교가 끝나면 날아오를 듯이 기분이 좋았던 적이 있어요. 그때 저의 모습과 시에 나온 아이들의 모습이 비슷한 것 같아요. — 나의 경험과 시의 장면을 견주면 맞아요.","scoring_points":["나의 경험을 썼는가","시의 장면과 견주었는가","완결된 문장인가"]},"explanation":["경험과 견주어요.","지도서 62쪽 예시예요.","문장으로."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L03_challenge#10','kor',2,2,'u1','L03','g2_2_kor_u1_L03_challenge','lesson_challenge','K2-2-u1-C3',4,'essay','teacher','「헬리콥터」에서 인상 깊은 표현 하나를 골라, 그 표현 때문에 떠오른 장면을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u1-C3","difficulty":4,"kind":"essay","stem":"「헬리콥터」에서 인상 깊은 표현 하나를 골라, 그 표현 때문에 떠오른 장면을 쓰세요.","answer_guide":{"answer":"예: 헬리콥터 소리를 흉내 낸 말을 보니 헬리콥터가 된 아이들의 모습을 더 실감 나게 상상할 수 있었어요. — 표현과 떠오른 장면이 함께 있으면 맞아요.","scoring_points":["표현을 골랐는가","그 표현으로 떠오른 장면을 썼는가","완결된 문장인가"]},"explanation":["표현에 주목해요.","지도서 62쪽 예시예요.","문장으로."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_basic#1','kor',2,2,'u1','L05','g2_2_kor_u1_L05_basic','lesson_basic','K2-2-u1-C4',1,'mc','auto','지도서 64쪽 「우산」에는 누가 나오나요?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":1,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"지도서 64쪽 「우산」에는 누가 나오나요?","options":[{"t":"「나」와 아빠","correct":true},{"t":"할머니와 손자","mis":"K2-2-u1-X05"},{"t":"강아지와 고양이","mis":"K2-2-u1-X05"}],"explanation":["「나」와 아빠예요.","비 오는 날 함께 걸어요.","지도서 65쪽이에요."],"asset":{"type":"scene","icon":"☔🧒👨","text":"지도서 64쪽 「우산」(유희윤) — 비 오는 날 「나」의 작은 우산이 앞에, 아빠의 큰 우산이 뒤에 걸어가는 모습을 산에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_basic#2','kor',2,2,'u1','L05','g2_2_kor_u1_L05_basic','lesson_basic','K2-2-u1-C4',1,'mc','auto','「짜장 요일」 — 오늘 급식으로 나온 음식은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":2,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「짜장 요일」 — 오늘 급식으로 나온 음식은?","options":[{"t":"짜장면","correct":true},{"t":"떡볶이","mis":"K2-2-u1-X05"},{"t":"비빔밥","mis":"K2-2-u1-X05"}],"explanation":["짜장면이에요.","14쪽을 다시 읽어요.","15쪽이에요."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
