INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_challenge#5','kor',2,2,'u1','L05','g2_2_kor_u1_L05_challenge','lesson_challenge','K2-2-u1-C4',3,'mc','auto','「친구의 웃는 소리도 짜장짜장 들린다」는 표현에서 떠오르는 장면으로 알맞은 것은?',ARRAY['K2-2-u1-X06','K2-2-u1-X02']::text[],false,'{"seq":5,"concept":"K2-2-u1-C4","difficulty":3,"kind":"mc","stem":"「친구의 웃는 소리도 짜장짜장 들린다」는 표현에서 떠오르는 장면으로 알맞은 것은?","options":[{"t":"마주 앉은 친구와 즐겁게 웃으며 짜장면을 먹는 모습","correct":true},{"t":"친구가 「짜장」이라는 노래를 부르는 모습","mis":"K2-2-u1-X06"},{"t":"친구가 혼자 우는 모습","mis":"K2-2-u1-X02"}],"explanation":["즐거운 웃음소리를 짜장에 빗대었어요.","글자 그대로가 아니에요.","17쪽 말풍선이에요."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_challenge#6','kor',2,2,'u1','L05','g2_2_kor_u1_L05_challenge','lesson_challenge','K2-2-u1-C1',3,'mc','auto','이 차시에서 시를 공부한 차례로 알맞은 것은?',ARRAY['K2-2-u1-X01']::text[],false,'{"seq":6,"concept":"K2-2-u1-C1","difficulty":3,"kind":"mc","stem":"이 차시에서 시를 공부한 차례로 알맞은 것은?","options":[{"t":"시 낭송하기 → 내용 파악하기 → 생각이나 느낌 나누기","correct":true},{"t":"생각이나 느낌 나누기 → 시 낭송하기 → 내용 파악하기","mis":"K2-2-u1-X01"},{"t":"내용 파악하기 → 생각이나 느낌 나누기 → 시 낭송하기","mis":"K2-2-u1-X01"}],"explanation":["읽고, 알고, 나눠요.","지도서 66쪽 학습 차례예요.","반응 중심 학습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_challenge#7','kor',2,2,'u1','L05','g2_2_kor_u1_L05_challenge','lesson_challenge','K2-2-u1-C5',3,'mc','auto','시에 대한 생각이나 느낌을 잘 표현한 친구를 칭찬하는 말로 알맞은 것은?',ARRAY['K2-2-u1-X07']::text[],false,'{"seq":7,"concept":"K2-2-u1-C5","difficulty":3,"kind":"mc","stem":"시에 대한 생각이나 느낌을 잘 표현한 친구를 칭찬하는 말로 알맞은 것은?","options":[{"t":"시의 표현을 들어 느낌을 말해서 시가 더 잘 이해됐어","correct":true},{"t":"목소리가 커서 잘했어","mis":"K2-2-u1-X07"},{"t":"제일 먼저 말해서 잘했어","mis":"K2-2-u1-X07"}],"explanation":["무엇을 잘 표현했는지 말해요.","지도서 67쪽이에요.","까닭을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_challenge#8','kor',2,2,'u1','L05','g2_2_kor_u1_L05_challenge','lesson_challenge','K2-2-u1-C4',4,'sa','auto','「짜장 요일」에서 아이들이 짜장면을 먹은 때는 언제인가요? (예: ○○ 시간)','{}'::text[],false,'{"seq":8,"concept":"K2-2-u1-C4","difficulty":4,"kind":"sa","stem":"「짜장 요일」에서 아이들이 짜장면을 먹은 때는 언제인가요? (예: ○○ 시간)","answer":["점심시간","점심 시간","급식 시간","급식시간","점심"],"explanation":["점심 급식 시간이에요.","17쪽 말풍선이에요.","시의 장면이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"점심시간에 짜장면을 먹으면서 신난 아이들의 모습이 생생하게 떠올라."},{"who":"친구 2","text":"친구의 웃는 소리가 짜장짜장 들린다는 표현이 재미있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_challenge#9','kor',2,2,'u1','L05','g2_2_kor_u1_L05_challenge','lesson_challenge','K2-2-u1-C5',4,'essay','teacher','「짜장 요일」과 비슷한 경험을 떠올려, 시에 대한 생각이나 느낌을 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u1-C5","difficulty":4,"kind":"essay","stem":"「짜장 요일」과 비슷한 경험을 떠올려, 시에 대한 생각이나 느낌을 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 지난 주말에 짜장면을 먹었는데 얼굴에 온통 짜장 양념이 묻었어요. 그래서 시를 읽으니 웃음이 났어요. — 비슷한 경험과 생각이나 느낌이 함께 있으면 맞아요.","scoring_points":["비슷한 경험을 썼는가","시에 대한 생각이나 느낌을 썼는가","완결된 문장인가"]},"explanation":["경험과 느낌을 이어요.","지도서 67쪽 예시예요.","두세 문장."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L05_challenge#10','kor',2,2,'u1','L05','g2_2_kor_u1_L05_challenge','lesson_challenge','K2-2-u1-C5',4,'essay','teacher','친구가 말한 「짜장 요일」의 생각이나 느낌을 듣고, 나와 비슷한 점과 다른 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u1-C5","difficulty":4,"kind":"essay","stem":"친구가 말한 「짜장 요일」의 생각이나 느낌을 듣고, 나와 비슷한 점과 다른 점을 쓰세요.","answer_guide":{"answer":"예: 친구는 웃는 소리 표현이 재미있다고 했고, 나도 그 표현이 재미있었어요. 그런데 나는 콧잔등에 묻은 짜장 점이 더 기억에 남았어요. — 비슷한 점과 다른 점이 둘 다 있으면 맞아요.","scoring_points":["비슷한 점을 썼는가","다른 점을 썼는가","친구의 생각을 존중했는가"]},"explanation":["견주며 감상해요.","다른 것도 괜찮아요.","지도서 66쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"점심시간에 짜장면을 먹으면서 신난 아이들의 모습이 생생하게 떠올라."},{"who":"친구 2","text":"친구의 웃는 소리가 짜장짜장 들린다는 표현이 재미있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_basic#1','kor',2,2,'u1','L07','g2_2_kor_u1_L07_basic','lesson_basic','K2-2-u1-C6',1,'mc','auto','「할머니와 하얀 집」 — 할머니가 살던 곳은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":1,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「할머니와 하얀 집」 — 할머니가 살던 곳은?","options":[{"t":"깊은 숲속 하얀 집","correct":true},{"t":"바닷가 빨간 집","mis":"K2-2-u1-X11"},{"t":"도시의 높은 건물","mis":"K2-2-u1-X11"}],"explanation":["숲속 하얀 집이에요.","첫 문장이에요.","18쪽이에요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_basic#2','kor',2,2,'u1','L07','g2_2_kor_u1_L07_basic','lesson_basic','K2-2-u1-C6',1,'mc','auto','할머니와 함께 살던 동물은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":2,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"할머니와 함께 살던 동물은?","options":[{"t":"하얀 고양이","correct":true},{"t":"검은 강아지","mis":"K2-2-u1-X11"},{"t":"노란 병아리","mis":"K2-2-u1-X11"}],"explanation":["하얀 고양이예요.","18쪽이에요.","인물을 확인해요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_basic#3','kor',2,2,'u1','L07','g2_2_kor_u1_L07_basic','lesson_basic','K2-2-u1-C6',1,'mc','auto','『국어』 23쪽 (1) — 할머니께서 집에 아무도 초대하지 않은 까닭은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":3,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"『국어』 23쪽 (1) — 할머니께서 집에 아무도 초대하지 않은 까닭은?","options":[{"t":"하얀 집에 뭐라도 묻을까 봐 걱정되었기 때문이에요","correct":true},{"t":"친구가 한 명도 없었기 때문이에요","mis":"K2-2-u1-X11"},{"t":"집이 너무 좁았기 때문이에요","mis":"K2-2-u1-X11"}],"explanation":["하얀 집을 지키려는 걱정이에요.","23쪽 예시 답안이에요.","19쪽을 다시 읽어요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
