INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_basic#6','kor',2,2,'u1','L07','g2_2_kor_u1_L07_basic','lesson_basic','K2-2-u1-C7',2,'match','auto','『국어』 25쪽 4번 — 이야기 상황과 할머니의 마음을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-2-u1-C7","difficulty":2,"kind":"match","stem":"『국어』 25쪽 4번 — 이야기 상황과 할머니의 마음을 이어 보세요.","pairs":[{"l":"하얀 고양이가 보이지 않음","r":"불안한 마음, 걱정되는 마음"},{"l":"집에서 새끼 고양이들을 발견함","r":"놀란 마음, 당황한 마음"},{"l":"새끼 고양이들이 자라며 여전히 집 안을 어지름","r":"어지럽혀도 괜찮은 마음, 즐거운 마음"}],"mis":"K2-2-u1-X12","explanation":["상황에 따라 마음이 달라요.","말과 행동이 근거예요.","25쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
