INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_basic#10','kor',2,2,'u1','L07','g2_2_kor_u1_L07_basic','lesson_basic','K2-2-u1-C6',3,'mc','auto','『국어』 24쪽 3번 — 이야기에서 맨 먼저 일어난 일은?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":10,"concept":"K2-2-u1-C6","difficulty":3,"kind":"mc","stem":"『국어』 24쪽 3번 — 이야기에서 맨 먼저 일어난 일은?","options":[{"t":"할머니는 하얀 집을 자랑스러워하며 하얀 고양이와 함께 살았다","correct":true},{"t":"하얀 고양이가 새끼를 낳았다","mis":"K2-2-u1-X10"},{"t":"집이 더는 하얗지 않았지만 할머니는 즐거웠다","mis":"K2-2-u1-X10"}],"explanation":["처음 장면이에요.","차례: 함께 삶 → 새끼 → 지침 → 즐거움.","24쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#1','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',2,'mc','auto','동기 유발 — 할머니가 집 안을 구석구석 청소하는 그림을 보고 짐작한 것으로 알맞은 것은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":1,"concept":"K2-2-u1-C7","difficulty":2,"kind":"mc","stem":"동기 유발 — 할머니가 집 안을 구석구석 청소하는 그림을 보고 짐작한 것으로 알맞은 것은?","options":[{"t":"청소를 좋아하고 깔끔한 사람일 것 같아요","correct":true},{"t":"수영을 좋아할 것 같아요","mis":"K2-2-u1-X12"},{"t":"축구 선수일 것 같아요","mis":"K2-2-u1-X12"}],"explanation":["그림을 근거로 짐작해요.","지도서 68쪽 예시예요.","개연성이 있어야 해요."],"asset":{"type":"scene","icon":"👵🧹🏠","text":"할머니가 집 안을 구석구석 청소하는 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#2','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',2,'mc','auto','할머니가 집에서 새끼 고양이들을 처음 발견했을 때의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":2,"concept":"K2-2-u1-C7","difficulty":2,"kind":"mc","stem":"할머니가 집에서 새끼 고양이들을 처음 발견했을 때의 마음은?","options":[{"t":"놀라고 당황한 마음","correct":true},{"t":"귀찮고 지루한 마음","mis":"K2-2-u1-X12"},{"t":"졸리고 피곤한 마음","mis":"K2-2-u1-X12"}],"explanation":["어쩔 줄 몰랐어요.","25쪽 예시 답안이에요.","행동이 근거예요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#3','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C6',3,'error','auto','한 친구가 줄거리를 정리했어요. 무엇이 잘못되었나요?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":3,"concept":"K2-2-u1-C6","difficulty":3,"kind":"error","stem":"한 친구가 줄거리를 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 차례가 섞였어요","correct":true,"mis_target":"K2-2-u1-X10"},{"t":"잘 정리했어요","mis":"K2-2-u1-X10"},{"t":"③이 맨 앞에 와야 해요","mis":"K2-2-u1-X10"}],"explanation":["②→①→③.","하얀 고양이가 먼저 사라졌다 돌아와요.","24쪽이에요."],"asset":{"type":"passage","lines":["① 새끼 고양이들이 하얀 집을 어지럽혔다.","② 하얀 고양이가 사라졌다가 며칠 뒤에 돌아왔다.","③ 할머니는 고양이들을 보는 것이 즐거워졌다."],"title":"차례가 섞인 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#4','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',3,'error','auto','한 친구가 「할머니는 고양이들이 어지를 때 끝까지 화가 났을 거야.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X13']::text[],false,'{"seq":4,"concept":"K2-2-u1-C7","difficulty":3,"kind":"error","stem":"한 친구가 「할머니는 고양이들이 어지를 때 끝까지 화가 났을 거야.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"이야기 끝에는 화내지 않고 고양이들을 보는 것이 즐거웠어요","correct":true,"mis_target":"K2-2-u1-X13"},{"t":"잘 말했어요","mis":"K2-2-u1-X13"},{"t":"할머니는 처음부터 즐거웠어요","mis":"K2-2-u1-X13"}],"explanation":["마음이 바뀌었어요.","끝 장면을 다시 읽어요.","22쪽이에요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#5','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',3,'mc','auto','지도서 72쪽 「형이 형인 까닭은?」 — 형이 쓰던 물건을 다 물려받는다며 투덜거린 동이의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":5,"concept":"K2-2-u1-C7","difficulty":3,"kind":"mc","stem":"지도서 72쪽 「형이 형인 까닭은?」 — 형이 쓰던 물건을 다 물려받는다며 투덜거린 동이의 마음은?","options":[{"t":"형만 새 물건을 사 줘서 서운하고 속상한 마음","correct":true},{"t":"형에게 고마운 마음","mis":"K2-2-u1-X12"},{"t":"신나고 기쁜 마음","mis":"K2-2-u1-X12"}],"explanation":["투덜거린 행동이 근거예요.","지도서 72쪽이에요.","말과 행동을 봐요."],"asset":{"type":"passage","lines":["동생 동이는 형이 쓰던 물건을 자기가 다 물려받는다며 투덜거렸어요.","형 남이는 「괜찮아, 괜찮아.」 하며 동생을 다독였어요."],"title":"지도서 72쪽 「형이 형인 까닭은?」(선안나) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#6','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',3,'mc','auto','「괜찮아, 괜찮아.」 하며 동생을 다독인 형 남이의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":6,"concept":"K2-2-u1-C7","difficulty":3,"kind":"mc","stem":"「괜찮아, 괜찮아.」 하며 동생을 다독인 형 남이의 마음은?","options":[{"t":"동생을 위로하고 걱정하는 마음","correct":true},{"t":"동생에게 화난 마음","mis":"K2-2-u1-X12"},{"t":"혼자 놀고 싶은 마음","mis":"K2-2-u1-X12"}],"explanation":["다독인 행동이 근거예요.","지도서 72쪽이에요.","말에 마음이 담겨요."],"asset":{"type":"passage","lines":["동생 동이는 형이 쓰던 물건을 자기가 다 물려받는다며 투덜거렸어요.","형 남이는 「괜찮아, 괜찮아.」 하며 동생을 다독였어요."],"title":"지도서 72쪽 「형이 형인 까닭은?」(선안나) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#7','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C6',3,'mc','auto','시간이 지나며 할머니 눈에 신기하게 보이기 시작한 것은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":7,"concept":"K2-2-u1-C6","difficulty":3,"kind":"mc","stem":"시간이 지나며 할머니 눈에 신기하게 보이기 시작한 것은?","options":[{"t":"새끼 고양이들이 저마다 생김새와 성격이 다르다는 것","correct":true},{"t":"집이 다시 하얘지는 것","mis":"K2-2-u1-X11"},{"t":"하얀 고양이가 사라지는 것","mis":"K2-2-u1-X11"}],"explanation":["고양이마다 달랐어요.","그래서 즐거워졌어요.","22쪽이에요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#8','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',4,'sa','auto','하얀 고양이가 돌아오자 할머니는 「후유.」 하고 가슴을 쓸어내렸어요. 이때의 마음을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u1-C7","difficulty":4,"kind":"sa","stem":"하얀 고양이가 돌아오자 할머니는 「후유.」 하고 가슴을 쓸어내렸어요. 이때의 마음을 두 글자로 쓰세요.","answer":["안심","다행","안도"],"explanation":["안심했어요.","「후유」가 근거예요.","20쪽이에요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#9','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',4,'essay','teacher','「할머니와 하얀 집」에서 한 장면을 골라, 할머니의 말이나 행동을 근거로 그때의 마음을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u1-C7","difficulty":4,"kind":"essay","stem":"「할머니와 하얀 집」에서 한 장면을 골라, 할머니의 말이나 행동을 근거로 그때의 마음을 쓰세요.","answer_guide":{"answer":"예: 새끼 고양이들이 어지른 것을 치우면서도 화내지 않고 웃으며 바라본 것을 보니, 할머니는 고양이들이 사랑스럽고 즐거웠던 것 같아요. — 장면·근거·마음이 있으면 맞아요.","scoring_points":["장면을 골랐는가","말이나 행동을 근거로 들었는가","마음을 썼는가"]},"explanation":["상황·말·행동이 근거.","25쪽 4번이에요.","문장으로."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L07_challenge#10','kor',2,2,'u1','L07','g2_2_kor_u1_L07_challenge','lesson_challenge','K2-2-u1-C7',4,'essay','teacher','인물 인터뷰 — 내가 할머니라면, 「새끼 고양이들이 집을 어지를 때 어떤 마음이었나요?」라는 물음에 어떻게 답할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u1-C7","difficulty":4,"kind":"essay","stem":"인물 인터뷰 — 내가 할머니라면, 「새끼 고양이들이 집을 어지를 때 어떤 마음이었나요?」라는 물음에 어떻게 답할지 쓰세요.","answer_guide":{"answer":"예: 처음에는 집이 더러워져서 속상하고 힘들었어요. 그런데 고양이마다 다른 모습을 보니 점점 즐거워졌어요. — 할머니가 되어 마음과 그 까닭을 말하면 맞아요.","scoring_points":["할머니가 되어 말했는가","마음을 썼는가","이야기 내용과 이어진 까닭이 있는가"]},"explanation":["인물이 되어 봐요.","지도서 72쪽 참고 자료예요.","마음과 까닭."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#1','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C6',1,'mc','auto','『국어』 31쪽 (1) — 엉뚱한 수리점은 무엇을 하는 곳인가요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":1,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"『국어』 31쪽 (1) — 엉뚱한 수리점은 무엇을 하는 곳인가요?","options":[{"t":"고장 난 물건을 고쳐 주는 곳","correct":true},{"t":"빵을 파는 곳","mis":"K2-2-u1-X11"},{"t":"책을 빌려주는 곳","mis":"K2-2-u1-X11"}],"explanation":["수리점은 물건을 고쳐요.","31쪽 예시 답안이에요.","제목을 떠올려요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#2','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C6',1,'mc','auto','어른들이 고칠 물건을 들고 줄을 서기 시작한 때는?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":2,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"어른들이 고칠 물건을 들고 줄을 서기 시작한 때는?","options":[{"t":"깜깜한 밤","correct":true},{"t":"이른 아침","mis":"K2-2-u1-X11"},{"t":"점심시간","mis":"K2-2-u1-X11"}],"explanation":["밤에 수리점에 불이 켜졌어요.","27쪽이에요.","때를 확인해요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
