INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#4','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C9',1,'mc','auto','『국어』 31쪽 보기 — 「도무지」의 뜻은?',ARRAY['K2-2-u1-X15']::text[],false,'{"seq":4,"concept":"K2-2-u1-C9","difficulty":1,"kind":"mc","stem":"『국어』 31쪽 보기 — 「도무지」의 뜻은?","options":[{"t":"아무리 해도","correct":true},{"t":"이리저리 깊이 생각하며","mis":"K2-2-u1-X15"},{"t":"흠이 없이 온전한","mis":"K2-2-u1-X15"}],"explanation":["도무지 = 아무리 해도.","보기를 다시 봐요.","31쪽 낱말 알기예요."],"asset":{"type":"passage","lines":["도무지: 아무리 해도.","곰곰이: 이리저리 깊이 생각하며.","멀쩡한: 흠이 없이 온전한."],"title":"『국어』 31쪽 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#5','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C9',2,'blank','auto','빈칸에 알맞은 낱말은?
