INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#7','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C6',2,'mc','auto','『국어』 31쪽 (2) — 물건을 넣으면 못 찾는 옷장 이야기를 듣고 소이는 뭐라고 했나요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":7,"concept":"K2-2-u1-C6","difficulty":2,"kind":"mc","stem":"『국어』 31쪽 (2) — 물건을 넣으면 못 찾는 옷장 이야기를 듣고 소이는 뭐라고 했나요?","options":[{"t":"숨바꼭질할 때 숨으면 좋겠다고 했어요","correct":true},{"t":"버리는 게 좋겠다고 했어요","mis":"K2-2-u1-X11"},{"t":"빨리 고치라고 했어요","mis":"K2-2-u1-X11"}],"explanation":["소이는 좋은 점을 찾았어요.","31쪽 예시 답안이에요.","28쪽이에요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#8','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C8',2,'mc','auto','『국어』 33쪽 — 제목을 「엉뚱한 수리점」이라고 한 까닭에 대한 생각으로 알맞은 것은?',ARRAY['K2-2-u1-X14']::text[],false,'{"seq":8,"concept":"K2-2-u1-C8","difficulty":2,"kind":"mc","stem":"『국어』 33쪽 — 제목을 「엉뚱한 수리점」이라고 한 까닭에 대한 생각으로 알맞은 것은?","options":[{"t":"소이가 보기에는 고치지 않아도 되는 물건을 어른들이 자꾸 고치려 하니까","correct":true},{"t":"수리점 간판이 거꾸로 달려 있으니까","mis":"K2-2-u1-X14"},{"t":"수리점이 낮에만 문을 여니까","mis":"K2-2-u1-X14"}],"explanation":["이야기 내용과 이어진 생각이에요.","33쪽 말풍선이에요.","근거를 들어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어른들이 물건을 고치지 않으면 이야기가 훨씬 더 재미있어질 것 같아."},{"who":"친구 2","text":"소이가 보기에는 고치지 않아도 되는 물건을 어른들이 자꾸 고치려 하니까 이야기의 제목을 ‘엉뚱한 수리점’이라고 한 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#9','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C8',2,'ox','auto','이야기에 대한 생각이나 느낌을 떠올릴 때 나의 경험은 말하면 안 돼요.',ARRAY['K2-2-u1-X07']::text[],false,'{"seq":9,"concept":"K2-2-u1-C8","difficulty":2,"kind":"ox","stem":"이야기에 대한 생각이나 느낌을 떠올릴 때 나의 경험은 말하면 안 돼요.","answer":"X","reason_options":[{"t":"나의 경험에서 비롯한 생각이나 느낌도 떠올릴 수 있으니까","correct":true},{"t":"이야기 속 글자만 말해야 하니까","mis":"K2-2-u1-X07"}],"mis":"K2-2-u1-X07","explanation":["경험도 실마리예요.","지도서 76~77쪽이에요.","인물·겪은 일·경험."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_basic#10','kor',2,2,'u1','L09','g2_2_kor_u1_L09_basic','lesson_basic','K2-2-u1-C6',3,'mc','auto','『국어』 32쪽 — 이야기에서 맨 나중에 일어난 일은?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":10,"concept":"K2-2-u1-C6","difficulty":3,"kind":"mc","stem":"『국어』 32쪽 — 이야기에서 맨 나중에 일어난 일은?","options":[{"t":"소이는 창밖 수리점을 보며 재미있는 것을 고치지 않겠다고 생각했다","correct":true},{"t":"소이는 친구들과 날이 어두워지는 것도 모르고 놀았다","mis":"K2-2-u1-X10"},{"t":"밤이 되자 수리점에 불이 켜지고 어른들이 줄을 섰다","mis":"K2-2-u1-X10"}],"explanation":["끝 장면이에요.","차례: 놀이 → 줄 → 빗자루 → 다짐.","32쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#1','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C8',2,'mc','auto','「엉뚱한 수리점」의 소이는 어떤 아이라고 생각하나요?',ARRAY['K2-2-u1-X14','K2-2-u1-X11']::text[],false,'{"seq":1,"concept":"K2-2-u1-C8","difficulty":2,"kind":"mc","stem":"「엉뚱한 수리점」의 소이는 어떤 아이라고 생각하나요?","options":[{"t":"고장 난 것 같은 물건에서도 재미있는 점을 찾아내는 아이","correct":true},{"t":"물건을 아주 잘 고치는 아이","mis":"K2-2-u1-X14"},{"t":"밤에 잠만 자는 아이","mis":"K2-2-u1-X11"}],"explanation":["좋은 점을 찾아요.","인물의 말이 근거예요.","지도서 76쪽이에요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#2','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C6',2,'mc','auto','이름을 고치고 싶어 하는 아저씨에게 소이는 어떻게 생각했나요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":2,"concept":"K2-2-u1-C6","difficulty":2,"kind":"mc","stem":"이름을 고치고 싶어 하는 아저씨에게 소이는 어떻게 생각했나요?","options":[{"t":"박공룡이라는 이름이 멋지다고 생각했어요","correct":true},{"t":"이름을 박부자로 고치라고 생각했어요","mis":"K2-2-u1-X11"},{"t":"이름이 이상하다고 생각했어요","mis":"K2-2-u1-X11"}],"explanation":["멋진 이름이라고 여겼어요.","29쪽이에요.","소이의 속마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#3','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C6',3,'error','auto','한 친구가 줄거리를 정리했어요. 무엇이 잘못되었나요?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":3,"concept":"K2-2-u1-C6","difficulty":3,"kind":"error","stem":"한 친구가 줄거리를 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 차례가 섞였어요","correct":true,"mis_target":"K2-2-u1-X10"},{"t":"잘 정리했어요","mis":"K2-2-u1-X10"},{"t":"③이 맨 앞에 와야 해요","mis":"K2-2-u1-X10"}],"explanation":["②→①→③.","소이는 먼저 친구들과 놀았어요.","32쪽이에요."],"asset":{"type":"passage","lines":["① 아저씨는 빗자루를 청소용으로 튼튼하게 고쳐 준다고 했다.","② 소이는 친구들과 날이 어두워지는 것도 모르고 놀았다.","③ 소이는 창밖 수리점을 보며 재미있는 것을 고치지 않겠다고 생각했다."],"title":"차례가 섞인 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
