INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#5','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C8',3,'mc','auto','지도서 79쪽 활동지 — 소이가 되어 편지에 답장한다면 알맞은 말은?',ARRAY['K2-2-u1-X14']::text[],false,'{"seq":5,"concept":"K2-2-u1-C8","difficulty":3,"kind":"mc","stem":"지도서 79쪽 활동지 — 소이가 되어 편지에 답장한다면 알맞은 말은?","options":[{"t":"청소기 소리가 크면 청소하는 걸 모두 알 수 있으니 좋은 점도 있는 것 같아","correct":true},{"t":"당장 청소기를 버려","mis":"K2-2-u1-X14"},{"t":"나는 잘 모르겠어","mis":"K2-2-u1-X14"}],"explanation":["소이처럼 좋은 점을 찾아요.","인물이 되어 답장해요.","지도서 79쪽이에요."],"asset":{"type":"passage","lines":["소이야, 안녕?","나는 네가 어른들이 고치고 싶어 하는 물건의 좋은 점을","찾아 주는 것을 보고 정말 지혜롭다고 생각했어.","나는 우리 집에 있는 청소기를 고치고 싶어.","청소기 소리가 엄청 큰데, 부모님께서 청소기를 돌리실 때마다","깜짝깜짝 놀라며 힘들어하셔.","청소기 소리가 안 나게 고치는 것을 너는 어떻게 생각하니?","너의 생각을 써서 답장을 보내 주면 좋겠어."],"title":"지도서 79쪽 활동지 — 소이에게 온 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
