INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#7','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C8',3,'mc','auto','「나도 동생을 강아지풀로 간지럼 태우며 논 적이 있어서 소이 마음을 알 것 같아.」는 어떤 방법으로 생각이나 느낌을 떠올린 것인가요?',ARRAY['K2-2-u1-X03','K2-2-u1-X07']::text[],false,'{"seq":7,"concept":"K2-2-u1-C8","difficulty":3,"kind":"mc","stem":"「나도 동생을 강아지풀로 간지럼 태우며 논 적이 있어서 소이 마음을 알 것 같아.」는 어떤 방법으로 생각이나 느낌을 떠올린 것인가요?","options":[{"t":"나의 경험에서 비롯한 생각이나 느낌 떠올리기","correct":true},{"t":"인물의 모습에 대한 생각이나 느낌 떠올리기","mis":"K2-2-u1-X03"},{"t":"책의 쪽수 세기","mis":"K2-2-u1-X07"}],"explanation":["「~적이 있어서」는 내 경험이에요.","지도서 76~77쪽이에요.","세 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#8','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C9',4,'sa','auto','「흠이 없이 온전한」이라는 뜻을 가진 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u1-C9","difficulty":4,"kind":"sa","stem":"「흠이 없이 온전한」이라는 뜻을 가진 낱말을 쓰세요.","answer":["멀쩡한","멀쩡하다"],"explanation":["멀쩡한이에요.","31쪽 보기예요.","넣어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#9','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C8',4,'essay','teacher','『국어』 33쪽 — 엉뚱한 수리점 아저씨께 고치고 싶은 물건과 고치고 싶은 내용을 부탁하는 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u1-C8","difficulty":4,"kind":"essay","stem":"『국어』 33쪽 — 엉뚱한 수리점 아저씨께 고치고 싶은 물건과 고치고 싶은 내용을 부탁하는 말을 쓰세요.","answer_guide":{"answer":"예: 고치고 싶은 물건은 우산이에요. 비가 올 때 우산이 저절로 펴지게 고쳐 주세요. — 물건과 고치고 싶은 내용이 있으면 맞아요.","scoring_points":["고치고 싶은 물건을 썼는가","고치고 싶은 내용을 썼는가","부탁하는 말로 썼는가"]},"explanation":["보기처럼 써요.","33쪽이에요.","붙임 1을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L09_challenge#10','kor',2,2,'u1','L09','g2_2_kor_u1_L09_challenge','lesson_challenge','K2-2-u1-C8',4,'essay','teacher','지도서 79쪽 활동지 — 소이가 되어 편지에 답장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u1-C8","difficulty":4,"kind":"essay","stem":"지도서 79쪽 활동지 — 소이가 되어 편지에 답장을 쓰세요.","answer_guide":{"answer":"예: 안녕? 청소기 소리가 크면 놀라시겠다. 그래도 큰 소리 덕분에 청소하는 줄 알 수 있잖아. 소리가 날 때 같이 도와드리면 어때? — 소이처럼 좋은 점을 찾거나 내 생각과 까닭이 있으면 맞아요.","scoring_points":["답장하는 말투로 썼는가","내 생각을 썼는가","까닭이 있는가"]},"explanation":["소이가 되어 써요.","지도서 79쪽이에요.","편지 꼴."],"asset":{"type":"passage","lines":["소이야, 안녕?","나는 네가 어른들이 고치고 싶어 하는 물건의 좋은 점을","찾아 주는 것을 보고 정말 지혜롭다고 생각했어.","나는 우리 집에 있는 청소기를 고치고 싶어.","청소기 소리가 엄청 큰데, 부모님께서 청소기를 돌리실 때마다","깜짝깜짝 놀라며 힘들어하셔.","청소기 소리가 안 나게 고치는 것을 너는 어떻게 생각하니?","너의 생각을 써서 답장을 보내 주면 좋겠어."],"title":"지도서 79쪽 활동지 — 소이에게 온 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
