INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_basic#8','kor',2,2,'u1','L11','g2_2_kor_u1_L11_basic','lesson_basic','K2-2-u1-C2',2,'ox','auto','소개할 이야기를 스스로 고르지 못하면 국어 시간에 배운 이야기 가운데에서 골라도 돼요.',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":8,"concept":"K2-2-u1-C2","difficulty":2,"kind":"ox","stem":"소개할 이야기를 스스로 고르지 못하면 국어 시간에 배운 이야기 가운데에서 골라도 돼요.","answer":"O","reason_options":[{"t":"배운 이야기 가운데 마음에 드는 것을 골라도 되니까","correct":true},{"t":"꼭 집에 있는 새 책이어야 하니까","mis":"K2-2-u1-X09"}],"mis":"K2-2-u1-X09","explanation":["배운 이야기도 좋아요.","지도서 80쪽이에요.","마음에 드는 것."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
