INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_basic#10','kor',2,2,'u1','L11','g2_2_kor_u1_L11_basic','lesson_basic','K2-2-u1-C5',3,'mc','auto','지도서 83쪽 요술 막대기 발표 — 친구가 재미있었다고 한 것은?',ARRAY['K2-2-u1-X06']::text[],false,'{"seq":10,"concept":"K2-2-u1-C5","difficulty":3,"kind":"mc","stem":"지도서 83쪽 요술 막대기 발표 — 친구가 재미있었다고 한 것은?","options":[{"t":"바람이 잘 통하는 마당을 냉장고라고 표현한 것","correct":true},{"t":"마당에 진짜 냉장고가 있는 것","mis":"K2-2-u1-X06"},{"t":"채소를 냉장고에 넣은 것","mis":"K2-2-u1-X06"}],"explanation":["마당을 냉장고에 빗대었어요.","글자 그대로가 아니에요.","지도서 83쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"「할머니표 냉장고」라는 시를 읽고 싱싱한 채소가 자라고 있는 넓은 마당이 떠올랐어. 시원한 바람이 잘 통하는 마당을 냉장고라고 표현한 것이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_challenge#1','kor',2,2,'u1','L11','g2_2_kor_u1_L11_challenge','lesson_challenge','K2-2-u1-C2',2,'mc','auto','병풍책을 만들 때 가장 먼저 하는 일은?',ARRAY['K2-2-u1-X17']::text[],false,'{"seq":1,"concept":"K2-2-u1-C2","difficulty":2,"kind":"mc","stem":"병풍책을 만들 때 가장 먼저 하는 일은?","options":[{"t":"도화지를 가로로 반을 접어 자르기","correct":true},{"t":"표지 붙이기","mis":"K2-2-u1-X17"},{"t":"테이프로 이어 붙이기","mis":"K2-2-u1-X17"}],"explanation":["접고 자르기부터.","34쪽 ①이에요.","차례대로."],"asset":{"type":"passage","lines":["① 도화지를 가로로 반을 접어 자른 뒤에, 자른 도화지 두 장을 빨간색 선을 따라 접는다.","② 도화지를 테이프로 이어 붙인다.","③ 맨 앞 장과 맨 뒷장에 두꺼운 종이를 붙여 표지를 만든다."],"title":"『국어』 34쪽 이야기 병풍책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
