INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_challenge#7','kor',2,2,'u1','L11','g2_2_kor_u1_L11_challenge','lesson_challenge','K2-2-u1-C2',3,'mc','auto','소개할 이야기를 정하지 못한 친구에게 해 줄 말로 알맞은 것은?',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":7,"concept":"K2-2-u1-C2","difficulty":3,"kind":"mc","stem":"소개할 이야기를 정하지 못한 친구에게 해 줄 말로 알맞은 것은?","options":[{"t":"국어 시간에 배운 이야기 가운데 마음에 드는 것을 골라 봐","correct":true},{"t":"아무거나 해","mis":"K2-2-u1-X09"},{"t":"소개하지 않아도 돼","mis":"K2-2-u1-X09"}],"explanation":["도와주는 말이에요.","지도서 80쪽이에요.","함께 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_challenge#8','kor',2,2,'u1','L11','g2_2_kor_u1_L11_challenge','lesson_challenge','K2-2-u1-C2',4,'sa','auto','아코디언처럼 접어 세워서 전시하기 좋은 책을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u1-C2","difficulty":4,"kind":"sa","stem":"아코디언처럼 접어 세워서 전시하기 좋은 책을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["병풍책"],"explanation":["병풍책이에요.","지도서 81쪽이에요.","34쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_challenge#9','kor',2,2,'u1','L11','g2_2_kor_u1_L11_challenge','lesson_challenge','K2-2-u1-C2',4,'essay','teacher','병풍책 안쪽에 쓸 글 — 소개하고 싶은 이야기의 한 장면과 그 장면에 대한 나의 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u1-C2","difficulty":4,"kind":"essay","stem":"병풍책 안쪽에 쓸 글 — 소개하고 싶은 이야기의 한 장면과 그 장면에 대한 나의 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 할머니가 새끼 고양이들을 웃으며 바라보는 장면이에요. 깨끗한 집보다 함께하는 즐거움이 더 소중하다는 생각이 들었어요. — 장면과 생각이나 느낌이 있으면 맞아요.","scoring_points":["장면을 썼는가","생각이나 느낌을 썼는가","완결된 문장인가"]},"explanation":["장면과 생각이나 느낌.","34쪽 4번이에요.","문장으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_L11_challenge#10','kor',2,2,'u1','L11','g2_2_kor_u1_L11_challenge','lesson_challenge','K2-2-u1-C2',4,'essay','teacher','지도서 89쪽 평가 — 소개하고 싶은 시나 이야기를 제목·주인공·떠오르는 장면·생각이나 느낌을 넣어 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u1-C2","difficulty":4,"kind":"essay","stem":"지도서 89쪽 평가 — 소개하고 싶은 시나 이야기를 제목·주인공·떠오르는 장면·생각이나 느낌을 넣어 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 『엉뚱한 수리점』을 소개할게요. 주인공 소이는 어른들이 고치려는 물건의 좋은 점을 찾아내요. 강아지풀로 간지럼을 태우자는 장면이 재미있었어요. — 소개할 내용이 두 가지 이상 있으면 맞아요.","scoring_points":["소개할 내용을 두 가지 이상 썼는가","생각이나 느낌을 썼는가","적절한 문장으로 썼는가"]},"explanation":["두 가지 이상.","지도서 88쪽 도달 기대 수준이에요.","문장으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#1','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C1',1,'mc','auto','시의 느낌이나 분위기를 살려 노래하듯이 소리 내어 읽는 것은?',ARRAY['K2-2-u1-X01']::text[],false,'{"seq":1,"concept":"K2-2-u1-C1","difficulty":1,"kind":"mc","stem":"시의 느낌이나 분위기를 살려 노래하듯이 소리 내어 읽는 것은?","options":[{"t":"낭송","correct":true},{"t":"받아쓰기","mis":"K2-2-u1-X01"},{"t":"베껴 쓰기","mis":"K2-2-u1-X01"}],"explanation":["낭송이에요.","8쪽이에요.","노래하듯."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#2','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C4',1,'mc','auto','「헬리콥터」에서 아이들이 신난 까닭은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":2,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「헬리콥터」에서 아이들이 신난 까닭은?","options":[{"t":"학교가 끝났기 때문이에요","correct":true},{"t":"소풍을 가기 때문이에요","mis":"K2-2-u1-X05"},{"t":"눈이 내렸기 때문이에요","mis":"K2-2-u1-X05"}],"explanation":["학교가 끝났어요.","11쪽이에요.","첫 부분."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#3','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C4',1,'mc','auto','「짜장 요일」에서 오늘 급식은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":3,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「짜장 요일」에서 오늘 급식은?","options":[{"t":"짜장면","correct":true},{"t":"김밥","mis":"K2-2-u1-X05"},{"t":"카레","mis":"K2-2-u1-X05"}],"explanation":["짜장면이에요.","14쪽이에요.","제목이 실마리."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#4','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C6',1,'mc','auto','「할머니와 하얀 집」에서 할머니가 날마다 한 일은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":4,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「할머니와 하얀 집」에서 할머니가 날마다 한 일은?","options":[{"t":"하얀 집을 청소했어요","correct":true},{"t":"바다에서 수영했어요","mis":"K2-2-u1-X11"},{"t":"학교에 다녔어요","mis":"K2-2-u1-X11"}],"explanation":["날마다 청소했어요.","19쪽이에요.","하얗게 지키려고."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#5','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C6',1,'mc','auto','「엉뚱한 수리점」의 주인공은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":5,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「엉뚱한 수리점」의 주인공은?","options":[{"t":"소이","correct":true},{"t":"할머니","mis":"K2-2-u1-X11"},{"t":"크니프","mis":"K2-2-u1-X11"}],"explanation":["소이예요.","26쪽이에요.","인물 확인."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#6','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C9',1,'mc','auto','『국어』 38쪽 — 「저 아이」를 줄여 말한 낱말은?',ARRAY['K2-2-u1-X16']::text[],false,'{"seq":6,"concept":"K2-2-u1-C9","difficulty":1,"kind":"mc","stem":"『국어』 38쪽 — 「저 아이」를 줄여 말한 낱말은?","options":[{"t":"걔","correct":true},{"t":"계","mis":"K2-2-u1-X16"},{"t":"개","mis":"K2-2-u1-X16"}],"explanation":["걔예요.","ㅒ가 들어가요.","38쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#7','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C4',1,'mc','auto','「서로」에서 서로를 걱정한 두 꽃은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":7,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「서로」에서 서로를 걱정한 두 꽃은?","options":[{"t":"채송화와 해바라기","correct":true},{"t":"장미와 튤립","mis":"K2-2-u1-X05"},{"t":"벚꽃과 국화","mis":"K2-2-u1-X05"}],"explanation":["채송화와 해바라기예요.","36쪽이에요.","두 꽃."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
