INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#9','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C3',2,'mc','auto','「방학식 날 신나게 집으로 달려가던 내 모습이 떠올랐어.」 — 어떤 방법인가요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":9,"concept":"K2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「방학식 날 신나게 집으로 달려가던 내 모습이 떠올랐어.」 — 어떤 방법인가요?","options":[{"t":"자신의 경험과 비교하며","correct":true},{"t":"인상 깊은 표현을 생각하며","mis":"K2-2-u1-X03"},{"t":"시의 내용을 생각하며","mis":"K2-2-u1-X03"}],"explanation":["내 모습 = 경험.","12쪽이에요.","세 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#10','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C5',2,'mc','auto','「짜장 요일」에 대한 생각이나 느낌으로 알맞은 것은?',ARRAY['K2-2-u1-X07']::text[],false,'{"seq":10,"concept":"K2-2-u1-C5","difficulty":2,"kind":"mc","stem":"「짜장 요일」에 대한 생각이나 느낌으로 알맞은 것은?","options":[{"t":"짜장면을 먹으며 신난 아이들이 생생하게 떠올라","correct":true},{"t":"나는 어제 늦잠을 잤어","mis":"K2-2-u1-X07"},{"t":"이 시는 글자가 많아","mis":"K2-2-u1-X07"}],"explanation":["시의 장면과 이어져요.","17쪽이에요.","상관없는 말은 아니에요."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#11','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C7',2,'mc','auto','하얀 고양이가 사라졌을 때 할머니의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":11,"concept":"K2-2-u1-C7","difficulty":2,"kind":"mc","stem":"하얀 고양이가 사라졌을 때 할머니의 마음은?","options":[{"t":"불안하고 걱정되는 마음","correct":true},{"t":"신나는 마음","mis":"K2-2-u1-X12"},{"t":"졸린 마음","mis":"K2-2-u1-X12"}],"explanation":["이러지도 저러지도 못했어요.","25쪽이에요.","행동이 근거."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
