INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#13','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C3',2,'ox','auto','시의 장면을 상상하는 것에는 정답이 하나만 있어요.',ARRAY['K2-2-u1-X04']::text[],false,'{"seq":13,"concept":"K2-2-u1-C3","difficulty":2,"kind":"ox","stem":"시의 장면을 상상하는 것에는 정답이 하나만 있어요.","answer":"X","reason_options":[{"t":"정답은 없지만 시의 말을 근거로 상상하니까","correct":true},{"t":"선생님이 말한 장면만 맞으니까","mis":"K2-2-u1-X04"}],"mis":"K2-2-u1-X04","explanation":["정답은 없어요.","근거는 있어요.","지도서 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#14','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C6',2,'mc','auto','「할머니와 하얀 집」에서 일어난 일의 차례로 알맞은 것은?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":14,"concept":"K2-2-u1-C6","difficulty":2,"kind":"mc","stem":"「할머니와 하얀 집」에서 일어난 일의 차례로 알맞은 것은?","options":[{"t":"하얀 고양이와 함께 삶 → 새끼를 낳음 → 지쳐 곯아떨어짐 → 하얗지 않아도 즐거움","correct":true},{"t":"새끼를 낳음 → 하얀 고양이와 함께 삶 → 즐거움 → 지침","mis":"K2-2-u1-X10"},{"t":"즐거움 → 지침 → 새끼를 낳음 → 함께 삶","mis":"K2-2-u1-X10"}],"explanation":["24쪽 차례예요.","처음·가운데·끝.","이야기 흐름."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#15','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C8',2,'mc','auto','「엉뚱한 수리점」 제목에 대한 생각으로 알맞은 것은?',ARRAY['K2-2-u1-X14']::text[],false,'{"seq":15,"concept":"K2-2-u1-C8","difficulty":2,"kind":"mc","stem":"「엉뚱한 수리점」 제목에 대한 생각으로 알맞은 것은?","options":[{"t":"고치지 않아도 되는 물건을 어른들이 자꾸 고치려 해서 엉뚱하다","correct":true},{"t":"수리점 간판이 엉뚱한 색이라서","mis":"K2-2-u1-X14"},{"t":"수리점이 아주 멀어서","mis":"K2-2-u1-X14"}],"explanation":["이야기와 이어진 생각.","33쪽이에요.","근거를 들어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어른들이 물건을 고치지 않으면 이야기가 훨씬 더 재미있어질 것 같아."},{"who":"친구 2","text":"소이가 보기에는 고치지 않아도 되는 물건을 어른들이 자꾸 고치려 하니까 이야기의 제목을 ‘엉뚱한 수리점’이라고 한 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
