INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#22','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C4',3,'error','auto','한 친구가 「「헬리콥터」에는 진짜 헬리콥터가 하늘을 나는 장면이 나와.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X06']::text[],false,'{"seq":22,"concept":"K2-2-u1-C4","difficulty":3,"kind":"error","stem":"한 친구가 「「헬리콥터」에는 진짜 헬리콥터가 하늘을 나는 장면이 나와.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"신난 아이들을 헬리콥터에 빗대었어요","correct":true,"mis_target":"K2-2-u1-X06"},{"t":"잘 말했어요","mis":"K2-2-u1-X06"},{"t":"비행기라고 해야 해요","mis":"K2-2-u1-X06"}],"explanation":["빗댄 말이에요.","지도서 61쪽이에요.","「~처럼」 넣어요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#23','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C2',4,'sa','auto','드소토 선생님이 큰 동물들의 이빨을 치료하려고 타고 올라간 것을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u1-C2","difficulty":4,"kind":"sa","stem":"드소토 선생님이 큰 동물들의 이빨을 치료하려고 타고 올라간 것을 쓰세요.","answer":["사다리"],"explanation":["사다리예요.","9쪽이에요.","말풍선을 읽어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"얼마 전에 『치과 의사 드소토 선생님』이라는 책을 읽었어. 지혜롭게 여우를 골탕 먹이는 드소토 선생님의 이야기가 정말 재미있었어."},{"who":"친구 2","text":"드소토 선생님은 쥐라서 몸집이 작은데 몸집이 큰 동물들의 이빨을 어떻게 치료해?"},{"who":"친구 1","text":"드소토 선생님은 사다리를 타고 올라가서 몸집이 큰 동물들의 이빨을 치료해 주었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#24','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C5',4,'essay','teacher','지도서 87쪽 평가 — 「서로」를 읽고 떠오르는 장면과 그 장면에서 든 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u1-C5","difficulty":4,"kind":"essay","stem":"지도서 87쪽 평가 — 「서로」를 읽고 떠오르는 장면과 그 장면에서 든 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 비가 세차게 내린 밤, 키 작은 채송화와 키 큰 해바라기가 서로를 걱정하는 장면이 떠올라요. 서로 아끼는 마음이 따뜻하게 느껴졌어요. — 장면과 생각이나 느낌이 함께 있으면 맞아요.","scoring_points":["장면을 구체적으로 썼는가","생각이나 느낌을 썼는가","시의 말을 근거로 했는가"]},"explanation":["장면 → 생각이나 느낌.","지도서 86쪽 평가 내용이에요.","37쪽 2번이에요."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_a#25','kor',2,2,'u1','','g2_2_kor_u1_review_a','unit_review','K2-2-u1-C2',4,'essay','teacher','지도서 89쪽 평가 — 학급 친구들에게 소개하고 싶은 시나 이야기를 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u1-C2","difficulty":4,"kind":"essay","stem":"지도서 89쪽 평가 — 학급 친구들에게 소개하고 싶은 시나 이야기를 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 『할머니와 하얀 집』을 소개할게요. 하얀 집을 지키던 할머니가 새끼 고양이들 덕분에 즐거워지는 이야기예요. 할머니가 화내지 않고 웃는 장면이 좋았어요. — 소개할 내용이 두 가지 이상 있으면 맞아요.","scoring_points":["소개할 내용을 두 가지 이상 썼는가","생각이나 느낌을 구체적으로 썼는가","적절한 문장으로 썼는가"]},"explanation":["두 가지 이상.","지도서 88쪽이에요.","문장으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#1','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C1',1,'mc','auto','『국어』 36쪽 「서로」를 공부할 때 가장 먼저 한 일은?',ARRAY['K2-2-u1-X01']::text[],false,'{"seq":1,"concept":"K2-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 36쪽 「서로」를 공부할 때 가장 먼저 한 일은?","options":[{"t":"장면을 떠올리며 낭송하기","correct":true},{"t":"글자 수 세기","mis":"K2-2-u1-X01"},{"t":"제목만 외우기","mis":"K2-2-u1-X01"}],"explanation":["낭송부터 해요.","36쪽 1번이에요.","장면을 떠올려요."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#2','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C4',1,'mc','auto','「헬리콥터」에서 아이들이 머리 위에서 돌린 것은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":2,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「헬리콥터」에서 아이들이 머리 위에서 돌린 것은?","options":[{"t":"신발주머니 가방","correct":true},{"t":"모자","mis":"K2-2-u1-X05"},{"t":"우산","mis":"K2-2-u1-X05"}],"explanation":["신발주머니 가방이에요.","10쪽이에요.","헬리콥터 날개처럼."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#3','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C4',1,'mc','auto','「짜장 요일」에서 짜장이 점처럼 묻은 곳은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":3,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「짜장 요일」에서 짜장이 점처럼 묻은 곳은?","options":[{"t":"콧잔등","correct":true},{"t":"발등","mis":"K2-2-u1-X05"},{"t":"손등","mis":"K2-2-u1-X05"}],"explanation":["콧잔등이에요.","15쪽 예시 답안이에요.","장면을 떠올려요."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#4','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C6',1,'mc','auto','「할머니와 하얀 집」에서 하얀 집을 난장판으로 만든 것은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":4,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「할머니와 하얀 집」에서 하얀 집을 난장판으로 만든 것은?","options":[{"t":"새끼 고양이들","correct":true},{"t":"다람쥐","mis":"K2-2-u1-X11"},{"t":"너구리","mis":"K2-2-u1-X11"}],"explanation":["새끼 고양이들이에요.","22쪽이에요.","쏟고 흘리고."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#5','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C6',1,'mc','auto','「엉뚱한 수리점」에서 소이가 처음에 친구들과 한 놀이는?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":5,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「엉뚱한 수리점」에서 소이가 처음에 친구들과 한 놀이는?","options":[{"t":"숨바꼭질","correct":true},{"t":"줄넘기","mis":"K2-2-u1-X11"},{"t":"축구","mis":"K2-2-u1-X11"}],"explanation":["숨바꼭질이에요.","26쪽이에요.","광장 분수대."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#6','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C9',1,'mc','auto','『국어』 38쪽 — 「이야기」를 줄여 말한 낱말은?',ARRAY['K2-2-u1-X16']::text[],false,'{"seq":6,"concept":"K2-2-u1-C9","difficulty":1,"kind":"mc","stem":"『국어』 38쪽 — 「이야기」를 줄여 말한 낱말은?","options":[{"t":"얘기","correct":true},{"t":"예기","mis":"K2-2-u1-X16"},{"t":"애기","mis":"K2-2-u1-X16"}],"explanation":["얘기예요.","ㅒ가 들어가요.","38쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#7','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C4',1,'mc','auto','「서로」에서 두 꽃이 서로를 걱정한 까닭은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":7,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「서로」에서 두 꽃이 서로를 걱정한 까닭은?","options":[{"t":"비가 세차게 내려서","correct":true},{"t":"햇볕이 너무 뜨거워서","mis":"K2-2-u1-X05"},{"t":"눈이 펑펑 내려서","mis":"K2-2-u1-X05"}],"explanation":["세찬 비 때문이에요.","36쪽이에요.","시의 말이 근거."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#8','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C2',1,'mc','auto','좋아하는 이야기를 소개할 때 넣으면 좋은 것은?',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":8,"concept":"K2-2-u1-C2","difficulty":1,"kind":"mc","stem":"좋아하는 이야기를 소개할 때 넣으면 좋은 것은?","options":[{"t":"좋아하는 까닭","correct":true},{"t":"책을 산 가게","mis":"K2-2-u1-X09"},{"t":"책의 색깔","mis":"K2-2-u1-X09"}],"explanation":["까닭을 넣어요.","지도서 59쪽이에요.","소개할 내용."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#9','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C3',2,'mc','auto','「헬리콥터 소리를 흉내 낸 말 때문에 장면이 실감 나.」 — 어떤 방법인가요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":9,"concept":"K2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「헬리콥터 소리를 흉내 낸 말 때문에 장면이 실감 나.」 — 어떤 방법인가요?","options":[{"t":"인상 깊은 표현을 생각하며","correct":true},{"t":"자신의 경험과 비교하며","mis":"K2-2-u1-X03"},{"t":"시의 내용을 생각하며","mis":"K2-2-u1-X03"}],"explanation":["표현에 주목.","지도서 62쪽이에요.","세 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#10','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C5',2,'mc','auto','「헬리콥터」에 대한 생각이나 느낌으로 알맞은 것은?',ARRAY['K2-2-u1-X07','K2-2-u1-X08']::text[],false,'{"seq":10,"concept":"K2-2-u1-C5","difficulty":2,"kind":"mc","stem":"「헬리콥터」에 대한 생각이나 느낌으로 알맞은 것은?","options":[{"t":"학교가 끝나 신난 마음이 나와 같아서 재미있어","correct":true},{"t":"헬리콥터는 비싸","mis":"K2-2-u1-X07"},{"t":"나는 공항에 가 봤어","mis":"K2-2-u1-X08"}],"explanation":["시의 장면·내 마음과 이어요.","지도서 62쪽이에요.","상관없는 말은 아니에요."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#11','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C7',2,'mc','auto','새끼 고양이들을 처음 발견한 할머니의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":11,"concept":"K2-2-u1-C7","difficulty":2,"kind":"mc","stem":"새끼 고양이들을 처음 발견한 할머니의 마음은?","options":[{"t":"놀라고 당황한 마음","correct":true},{"t":"지루한 마음","mis":"K2-2-u1-X12"},{"t":"화난 마음","mis":"K2-2-u1-X12"}],"explanation":["어쩔 줄 몰랐어요.","25쪽이에요.","행동이 근거."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
