INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#13','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C5',2,'ox','auto','친구와 생각이나 느낌을 나누면 시를 더 잘 이해할 수 있어요.',ARRAY['K2-2-u1-X04']::text[],false,'{"seq":13,"concept":"K2-2-u1-C5","difficulty":2,"kind":"ox","stem":"친구와 생각이나 느낌을 나누면 시를 더 잘 이해할 수 있어요.","answer":"O","reason_options":[{"t":"친구의 생각을 듣고 내 감상이 넓어지니까","correct":true},{"t":"친구 생각을 그대로 따라 해야 하니까","mis":"K2-2-u1-X04"}],"mis":"K2-2-u1-X04","explanation":["감상이 넓어져요.","지도서 67쪽이에요.","다양성을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#14','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C6',2,'mc','auto','「엉뚱한 수리점」에서 일어난 일의 차례로 알맞은 것은?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":14,"concept":"K2-2-u1-C6","difficulty":2,"kind":"mc","stem":"「엉뚱한 수리점」에서 일어난 일의 차례로 알맞은 것은?","options":[{"t":"친구들과 놀이 → 어른들이 줄을 섬 → 빗자루 부탁 → 고치지 않겠다는 다짐","correct":true},{"t":"빗자루 부탁 → 친구들과 놀이 → 다짐 → 줄을 섬","mis":"K2-2-u1-X10"},{"t":"다짐 → 빗자루 부탁 → 줄을 섬 → 친구들과 놀이","mis":"K2-2-u1-X10"}],"explanation":["32쪽 차례예요.","처음·가운데·끝.","이야기 흐름."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
