INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#18','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C8',3,'error','auto','「엉뚱한 수리점」을 읽은 생각이나 느낌을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#19','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C6',3,'error','auto','한 친구가 「엉뚱한 수리점」 줄거리를 정리했어요. 무엇이 잘못되었나요?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":19,"concept":"K2-2-u1-C6","difficulty":3,"kind":"error","stem":"한 친구가 「엉뚱한 수리점」 줄거리를 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 차례가 섞였어요","correct":true,"mis_target":"K2-2-u1-X10"},{"t":"잘 정리했어요","mis":"K2-2-u1-X10"},{"t":"③이 맨 앞에 와야 해요","mis":"K2-2-u1-X10"}],"explanation":["②→①→③.","32쪽이에요.","처음부터."],"asset":{"type":"passage","lines":["① 아저씨는 빗자루를 청소용으로 튼튼하게 고쳐 준다고 했다.","② 소이는 친구들과 날이 어두워지는 것도 모르고 놀았다.","③ 소이는 창밖 수리점을 보며 재미있는 것을 고치지 않겠다고 생각했다."],"title":"차례가 섞인 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#20','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C7',3,'mc','auto','할머니가 「언젠가부터 걱정하거나 화내지 않았다」는 것으로 알 수 있는 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":20,"concept":"K2-2-u1-C7","difficulty":3,"kind":"mc","stem":"할머니가 「언젠가부터 걱정하거나 화내지 않았다」는 것으로 알 수 있는 마음은?","options":[{"t":"어지럽혀도 괜찮고, 고양이들을 보는 것이 즐거운 마음","correct":true},{"t":"고양이들이 미운 마음","mis":"K2-2-u1-X12"},{"t":"집을 떠나고 싶은 마음","mis":"K2-2-u1-X12"}],"explanation":["행동이 근거.","22쪽이에요.","마음이 바뀌었어요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#21','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C9',3,'blank','auto','빈칸에 알맞은 낱말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#22','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C6',3,'error','auto','한 친구가 「할머니는 집이 좁아서 아무도 초대하지 않았어.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":22,"concept":"K2-2-u1-C6","difficulty":3,"kind":"error","stem":"한 친구가 「할머니는 집이 좁아서 아무도 초대하지 않았어.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"하얀 집에 뭐라도 묻을까 봐 걱정되어 초대하지 않았어요","correct":true,"mis_target":"K2-2-u1-X11"},{"t":"잘 말했어요","mis":"K2-2-u1-X11"},{"t":"친구가 없어서라고 해야 해요","mis":"K2-2-u1-X11"}],"explanation":["까닭을 다시 읽어요.","23쪽이에요.","줄을 짚어요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#23','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C2',4,'sa','auto','아코디언처럼 접어 세워 전시하기 좋은 책을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u1-C2","difficulty":4,"kind":"sa","stem":"아코디언처럼 접어 세워 전시하기 좋은 책을 쓰세요.","answer":["병풍책"],"explanation":["병풍책이에요.","34쪽이에요.","지도서 81쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#24','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C5',4,'essay','teacher','자신이 읽은 시 한 편을 골라 제목·장면·그 장면에서 떠오르는 생각이나 느낌을 정리해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u1-C5","difficulty":4,"kind":"essay","stem":"자신이 읽은 시 한 편을 골라 제목·장면·그 장면에서 떠오르는 생각이나 느낌을 정리해 쓰세요.","answer_guide":{"answer":"예: 제목: 짜장 요일 / 장면: 콧잔등에 짜장이 묻은 친구들 / 생각이나 느낌: 친구와 함께 먹는 점심이 즐거워 보였어요. — 세 칸이 모두 있으면 맞아요.","scoring_points":["제목을 썼는가","장면을 썼는가","생각이나 느낌을 썼는가"]},"explanation":["세 칸을 채워요.","지도서 87쪽 평가 예시예요.","바른 자세로 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_b#25','kor',2,2,'u1','','g2_2_kor_u1_review_b','unit_review','K2-2-u1-C2',4,'essay','teacher','좋아하는 이야기를 골라 제목·주인공·기억에 남는 장면을 넣어 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u1-C2","difficulty":4,"kind":"essay","stem":"좋아하는 이야기를 골라 제목·주인공·기억에 남는 장면을 넣어 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 『엉뚱한 수리점』의 주인공은 소이예요. 소이가 강아지풀로 간지럼을 태우면 재미있다고 말하는 장면이 기억에 남아요. — 세 가지가 있으면 맞아요.","scoring_points":["제목을 썼는가","주인공을 썼는가","기억에 남는 장면을 썼는가"]},"explanation":["세 가지를 넣어요.","지도서 89쪽이에요.","문장으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#1','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C1',1,'mc','auto','「짜장 요일」을 짝과 한 줄씩 주고받으며 읽는 낭송 방법은?',ARRAY['K2-2-u1-X01']::text[],false,'{"seq":1,"concept":"K2-2-u1-C1","difficulty":1,"kind":"mc","stem":"「짜장 요일」을 짝과 한 줄씩 주고받으며 읽는 낭송 방법은?","options":[{"t":"서로 번갈아 가며 낭송하기","correct":true},{"t":"흉내 내는 말을 함께 낭송하기","mis":"K2-2-u1-X01"},{"t":"눈으로만 읽기","mis":"K2-2-u1-X01"}],"explanation":["번갈아 가며 읽어요.","16쪽이에요.","여러 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#2','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C4',1,'mc','auto','「헬리콥터」에서 아이들을 빗댄 것은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":2,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「헬리콥터」에서 아이들을 빗댄 것은?","options":[{"t":"헬리콥터","correct":true},{"t":"자동차","mis":"K2-2-u1-X05"},{"t":"배","mis":"K2-2-u1-X05"}],"explanation":["헬리콥터예요.","제목이 실마리예요.","빗댄 말."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#3','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C4',1,'mc','auto','「짜장 요일」에서 입가에 생긴 것을 무엇에 빗대었나요?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":3,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「짜장 요일」에서 입가에 생긴 것을 무엇에 빗대었나요?","options":[{"t":"수염","correct":true},{"t":"눈썹","mis":"K2-2-u1-X05"},{"t":"머리카락","mis":"K2-2-u1-X05"}],"explanation":["짜장 수염이에요.","15쪽이에요.","빗댄 말."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#4','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C6',1,'mc','auto','「할머니와 하얀 집」에서 사라졌다가 며칠 뒤 돌아온 것은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":4,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「할머니와 하얀 집」에서 사라졌다가 며칠 뒤 돌아온 것은?","options":[{"t":"하얀 고양이","correct":true},{"t":"할머니","mis":"K2-2-u1-X11"},{"t":"새","mis":"K2-2-u1-X11"}],"explanation":["하얀 고양이예요.","20쪽이에요.","할머니는 걱정했어요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#5','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C6',1,'mc','auto','「엉뚱한 수리점」에서 소이가 날게 해 달라고 한 물건은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":5,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「엉뚱한 수리점」에서 소이가 날게 해 달라고 한 물건은?","options":[{"t":"빗자루","correct":true},{"t":"의자","mis":"K2-2-u1-X11"},{"t":"옷장","mis":"K2-2-u1-X11"}],"explanation":["빗자루예요.","30쪽이에요.","새처럼 날고 싶었어요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#6','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C9',1,'mc','auto','바른 몸가짐으로 웃어른을 대하는 것을 뜻하는 낱말은?',ARRAY['K2-2-u1-X16']::text[],false,'{"seq":6,"concept":"K2-2-u1-C9","difficulty":1,"kind":"mc","stem":"바른 몸가짐으로 웃어른을 대하는 것을 뜻하는 낱말은?","options":[{"t":"예의","correct":true},{"t":"얘의","mis":"K2-2-u1-X16"},{"t":"애의","mis":"K2-2-u1-X16"}],"explanation":["예의예요.","ㅖ가 들어가요.","38쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#7','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C4',1,'mc','auto','「서로」에서 두 꽃이 서로를 걱정한 때는?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":7,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「서로」에서 두 꽃이 서로를 걱정한 때는?","options":[{"t":"밤새","correct":true},{"t":"점심시간","mis":"K2-2-u1-X05"},{"t":"아침 일찍 잠깐","mis":"K2-2-u1-X05"}],"explanation":["밤새 걱정했어요.","36쪽이에요.","때를 확인해요."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#8','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C2',1,'mc','auto','『국어』 34쪽에서 이야기를 소개하려고 만든 것은?',ARRAY['K2-2-u1-X17']::text[],false,'{"seq":8,"concept":"K2-2-u1-C2","difficulty":1,"kind":"mc","stem":"『국어』 34쪽에서 이야기를 소개하려고 만든 것은?","options":[{"t":"이야기 병풍책","correct":true},{"t":"종이비행기","mis":"K2-2-u1-X17"},{"t":"딱지","mis":"K2-2-u1-X17"}],"explanation":["병풍책이에요.","34쪽이에요.","이런 활동 어때요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#9','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C3',2,'mc','auto','「학교가 끝나자 신발주머니를 돌리며 집으로 가는 아이들이 떠올라.」 — 어떤 방법인가요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":9,"concept":"K2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「학교가 끝나자 신발주머니를 돌리며 집으로 가는 아이들이 떠올라.」 — 어떤 방법인가요?","options":[{"t":"시의 내용을 생각하며","correct":true},{"t":"자신의 경험과 비교하며","mis":"K2-2-u1-X03"},{"t":"인상 깊은 표현을 생각하며","mis":"K2-2-u1-X03"}],"explanation":["줄거리 = 내용.","12쪽이에요.","세 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#10','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C5',2,'mc','auto','「우산」에 대한 생각이나 느낌으로 알맞은 것은?',ARRAY['K2-2-u1-X07']::text[],false,'{"seq":10,"concept":"K2-2-u1-C5","difficulty":2,"kind":"mc","stem":"「우산」에 대한 생각이나 느낌으로 알맞은 것은?","options":[{"t":"아빠와 「나」의 사이가 무척 좋은 것 같아","correct":true},{"t":"우산은 파란색이 좋아","mis":"K2-2-u1-X07"},{"t":"비 오는 날은 학교에 안 가","mis":"K2-2-u1-X07"}],"explanation":["시의 장면과 이어요.","지도서 65쪽이에요.","상관없는 말은 아니에요."],"asset":{"type":"scene","icon":"☔🧒👨","text":"지도서 64쪽 「우산」(유희윤) — 비 오는 날 「나」의 작은 우산이 앞에, 아빠의 큰 우산이 뒤에 걸어가는 모습을 산에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#11','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C7',2,'mc','auto','아저씨가 빗자루를 청소용으로만 고쳐 준다고 했을 때 소이의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":11,"concept":"K2-2-u1-C7","difficulty":2,"kind":"mc","stem":"아저씨가 빗자루를 청소용으로만 고쳐 준다고 했을 때 소이의 마음은?","options":[{"t":"실망하고 놀란 마음","correct":true},{"t":"기쁘고 신나는 마음","mis":"K2-2-u1-X12"},{"t":"졸리고 피곤한 마음","mis":"K2-2-u1-X12"}],"explanation":["도망치듯 집으로 갔어요.","30쪽이에요.","행동이 근거."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#12','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C9',2,'match','auto','모음과 입 모양을 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-2-u1-C9","difficulty":2,"kind":"match","stem":"모음과 입 모양을 이어 보세요.","pairs":[{"l":"ㅒ","r":"ㅣ에서 ㅐ로"},{"l":"ㅖ","r":"ㅣ에서 ㅔ로"}],"mis":"K2-2-u1-X16","explanation":["ㅒ는 턱이 조금 더 내려가요.","38쪽 2번이에요.","선생님 입 모양을 따라 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#13','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C7',2,'ox','auto','인물의 마음은 이야기의 상황과 인물의 말이나 행동을 보고 상상해요.',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":13,"concept":"K2-2-u1-C7","difficulty":2,"kind":"ox","stem":"인물의 마음은 이야기의 상황과 인물의 말이나 행동을 보고 상상해요.","answer":"O","reason_options":[{"t":"상황·말·행동이 마음을 짐작하는 근거니까","correct":true},{"t":"내 기분대로 정하면 되니까","mis":"K2-2-u1-X12"}],"mis":"K2-2-u1-X12","explanation":["근거로 상상해요.","지도서 71쪽이에요.","지나친 상상을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#14','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C6',2,'mc','auto','「할머니와 하얀 집」에서 새끼 고양이들이 나타난 뒤에 일어난 일은?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":14,"concept":"K2-2-u1-C6","difficulty":2,"kind":"mc","stem":"「할머니와 하얀 집」에서 새끼 고양이들이 나타난 뒤에 일어난 일은?","options":[{"t":"집이 점점 난장판이 되었다","correct":true},{"t":"할머니가 하얀 고양이와 살기 시작했다","mis":"K2-2-u1-X10"},{"t":"하얀 고양이가 처음 사라졌다","mis":"K2-2-u1-X10"}],"explanation":["새끼 → 난장판.","22쪽이에요.","차례를 생각해요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#15','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C8',2,'mc','auto','「어른들이 물건을 고치지 않으면 이야기가 더 재미있어질 것 같아.」는 무엇에 대한 생각인가요?',ARRAY['K2-2-u1-X07']::text[],false,'{"seq":15,"concept":"K2-2-u1-C8","difficulty":2,"kind":"mc","stem":"「어른들이 물건을 고치지 않으면 이야기가 더 재미있어질 것 같아.」는 무엇에 대한 생각인가요?","options":[{"t":"인물이 겪은 일에 대한 생각","correct":true},{"t":"책 가격에 대한 생각","mis":"K2-2-u1-X07"},{"t":"날씨에 대한 생각","mis":"K2-2-u1-X07"}],"explanation":["어른들이 고치려는 일이에요.","33쪽이에요.","겪은 일."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어른들이 물건을 고치지 않으면 이야기가 훨씬 더 재미있어질 것 같아."},{"who":"친구 2","text":"소이가 보기에는 고치지 않아도 되는 물건을 어른들이 자꾸 고치려 하니까 이야기의 제목을 ‘엉뚱한 수리점’이라고 한 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#16','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C9',2,'mc','auto','바르게 쓴 문장은?',ARRAY['K2-2-u1-X16']::text[],false,'{"seq":16,"concept":"K2-2-u1-C9","difficulty":2,"kind":"mc","stem":"바르게 쓴 문장은?","options":[{"t":"친구와 재미있는 얘기를 나누었다.","correct":true},{"t":"친구와 재미있는 예기를 나누었다.","mis":"K2-2-u1-X16"},{"t":"친구와 재미있는 애기를 나누었다.","mis":"K2-2-u1-X16"}],"explanation":["이야기 → 얘기.","38쪽이에요.","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
