INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#18','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C5',3,'error','auto','「짜장 요일」과 비슷한 경험을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#19','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C2',3,'error','auto','한 친구가 병풍책 만드는 방법을 정리했어요. 무엇이 잘못되었나요?',ARRAY['K2-2-u1-X17']::text[],false,'{"seq":19,"concept":"K2-2-u1-C2","difficulty":3,"kind":"error","stem":"한 친구가 병풍책 만드는 방법을 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 차례가 섞였어요","correct":true,"mis_target":"K2-2-u1-X17"},{"t":"잘 정리했어요","mis":"K2-2-u1-X17"},{"t":"③이 맨 앞에 와야 해요","mis":"K2-2-u1-X17"}],"explanation":["②→③→①.","34쪽이에요.","표지는 마지막."],"asset":{"type":"passage","lines":["① 맨 앞 장과 맨 뒷장에 두꺼운 종이를 붙여 표지를 만든다.","② 도화지를 반 접어 자르고 선을 따라 접는다.","③ 도화지를 테이프로 이어 붙인다."],"title":"차례가 섞인 만드는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#20','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C7',3,'mc','auto','지도서 72쪽 — 형 쓰던 물건을 다 물려받는다며 투덜거린 동이의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":20,"concept":"K2-2-u1-C7","difficulty":3,"kind":"mc","stem":"지도서 72쪽 — 형 쓰던 물건을 다 물려받는다며 투덜거린 동이의 마음은?","options":[{"t":"서운하고 속상한 마음","correct":true},{"t":"고맙고 기쁜 마음","mis":"K2-2-u1-X12"},{"t":"신나는 마음","mis":"K2-2-u1-X12"}],"explanation":["투덜거림이 근거.","지도서 72쪽이에요.","말과 행동."],"asset":{"type":"passage","lines":["동생 동이는 형이 쓰던 물건을 자기가 다 물려받는다며 투덜거렸어요.","형 남이는 「괜찮아, 괜찮아.」 하며 동생을 다독였어요."],"title":"지도서 72쪽 「형이 형인 까닭은?」(선안나) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#21','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C9',3,'blank','auto','빈칸에 알맞은 낱말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#22','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C6',3,'error','auto','한 친구가 「소이는 옷장을 버리라고 했어.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":22,"concept":"K2-2-u1-C6","difficulty":3,"kind":"error","stem":"한 친구가 「소이는 옷장을 버리라고 했어.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"숨바꼭질할 때 숨으면 좋겠다고 했어요","correct":true,"mis_target":"K2-2-u1-X11"},{"t":"잘 말했어요","mis":"K2-2-u1-X11"},{"t":"옷장을 크게 고치라고 했어요","mis":"K2-2-u1-X11"}],"explanation":["소이는 좋은 점을 찾았어요.","31쪽이에요.","줄을 짚어요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#23','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C3',4,'sa','auto','시의 장면을 상상하는 세 가지 방법 가운데 「저도 ~한 적이 있어요」처럼 떠올리는 방법에 들어가는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u1-C3","difficulty":4,"kind":"sa","stem":"시의 장면을 상상하는 세 가지 방법 가운데 「저도 ~한 적이 있어요」처럼 떠올리는 방법에 들어가는 두 글자 낱말을 쓰세요.","answer":["경험"],"explanation":["경험이에요.","12쪽이에요.","나의 일과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#24','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C7',4,'essay','teacher','「할머니와 하얀 집」에서 가장 인상 깊은 장면을 고르고, 그때 할머니의 마음과 나의 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u1-C7","difficulty":4,"kind":"essay","stem":"「할머니와 하얀 집」에서 가장 인상 깊은 장면을 고르고, 그때 할머니의 마음과 나의 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 할머니가 새끼 고양이들을 웃으며 바라보는 장면이 인상 깊었어요. 할머니는 즐거웠을 것 같아요. 나도 반려동물과 놀 때 즐거웠던 일이 생각났어요. — 장면·인물의 마음·나의 생각이나 느낌이 있으면 맞아요.","scoring_points":["장면을 골랐는가","인물의 마음을 썼는가","나의 생각이나 느낌을 썼는가"]},"explanation":["장면·마음·느낌.","25쪽이에요.","문장으로."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_c#25','kor',2,2,'u1','','g2_2_kor_u1_review_c','unit_review','K2-2-u1-C8',4,'essay','teacher','엉뚱한 수리점 아저씨께 고치고 싶은 물건과 고치고 싶은 내용을 부탁하는 글을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u1-C8","difficulty":4,"kind":"essay","stem":"엉뚱한 수리점 아저씨께 고치고 싶은 물건과 고치고 싶은 내용을 부탁하는 글을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 제 연필을 저절로 깎이게 고쳐 주세요. 연필을 깎다가 자주 부러뜨려서 속상하거든요. — 물건·내용·까닭이 있으면 맞아요.","scoring_points":["물건을 썼는가","고치고 싶은 내용을 썼는가","까닭을 썼는가"]},"explanation":["까닭을 넣어요.","33쪽이에요.","부탁하는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#1','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C1',1,'mc','auto','낭송할 때 알맞은 모습은?',ARRAY['K2-2-u1-X01']::text[],false,'{"seq":1,"concept":"K2-2-u1-C1","difficulty":1,"kind":"mc","stem":"낭송할 때 알맞은 모습은?","options":[{"t":"재미있거나 생생한 표현의 느낌을 살려 읽어요","correct":true},{"t":"아주 빠르게 중얼거려요","mis":"K2-2-u1-X01"},{"t":"소리 없이 입만 움직여요","mis":"K2-2-u1-X01"}],"explanation":["느낌을 살려요.","지도서 61쪽이에요.","장면이 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#2','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C3',1,'mc','auto','「헬리콥터」에서 헬리콥터 소리를 흉내 낸 말은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":2,"concept":"K2-2-u1-C3","difficulty":1,"kind":"mc","stem":"「헬리콥터」에서 헬리콥터 소리를 흉내 낸 말은?","options":[{"t":"두두두두두","correct":true},{"t":"부릉부릉","mis":"K2-2-u1-X05"},{"t":"칙칙폭폭","mis":"K2-2-u1-X05"}],"explanation":["「두두두두두」예요.","11쪽 예시 답안이에요.","흉내 내는 말."],"asset":{"type":"scene","icon":"🎒🚁🏫","text":"『국어』 10~11쪽 「헬리콥터」(이병승) — 학교가 끝나 신발주머니 가방을 머리 위에서 돌리며 달려가는 아이들을 헬리콥터에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#3','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C4',1,'mc','auto','「짜장 요일」에서 아이들이 짜장면을 먹은 곳은?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":3,"concept":"K2-2-u1-C4","difficulty":1,"kind":"mc","stem":"「짜장 요일」에서 아이들이 짜장면을 먹은 곳은?","options":[{"t":"학교 급식 시간","correct":true},{"t":"짜장면 가게","mis":"K2-2-u1-X05"},{"t":"할머니 댁","mis":"K2-2-u1-X05"}],"explanation":["급식이에요.","14쪽이에요.","장면을 떠올려요."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#4','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C6',1,'mc','auto','「할머니와 하얀 집」 끝에서 할머니의 집은 어떻게 되었나요?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":4,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「할머니와 하얀 집」 끝에서 할머니의 집은 어떻게 되었나요?","options":[{"t":"눈처럼 하얗지 않지만 할머니는 괜찮대요","correct":true},{"t":"다시 새하얘졌어요","mis":"K2-2-u1-X11"},{"t":"할머니가 이사를 갔어요","mis":"K2-2-u1-X11"}],"explanation":["하얗지 않아도 괜찮아요.","22쪽이에요.","즐거운 일이 많아졌어요."],"asset":{"type":"passage","lines":["깊은 숲속 하얀 집에 할머니가 하얀 고양이와 함께 살았어요.","할머니는 집이 더러워질까 봐 걱정하며 날마다 청소했고,","뭐라도 묻을까 봐 아무도 초대하지 않았어요.","사라졌던 하얀 고양이가 며칠 뒤 돌아오자 할머니는 「후유.」 했어요.","그러던 어느 날 새끼 고양이들이 나타나 집은 난장판이 되었어요.","할머니는 날마다 치우고 닦다가 지쳐 잠들었어요.","그러다 고양이마다 성격이 다른 것이 보이자 화내지 않고 즐거워졌어요.","집은 이제 하얗지 않지만 할머니는 괜찮대요."],"title":"「할머니와 하얀 집」(이윤우) 간추림 — 『국어』 18~22쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#5','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C6',1,'mc','auto','「엉뚱한 수리점」에서 소이가 마지막에 한 생각은?',ARRAY['K2-2-u1-X11']::text[],false,'{"seq":5,"concept":"K2-2-u1-C6","difficulty":1,"kind":"mc","stem":"「엉뚱한 수리점」에서 소이가 마지막에 한 생각은?","options":[{"t":"재미있는 것을 절대 고치지 않겠다","correct":true},{"t":"모든 물건을 고쳐야겠다","mis":"K2-2-u1-X11"},{"t":"수리점에서 일하고 싶다","mis":"K2-2-u1-X11"}],"explanation":["고치지 않겠다고 했어요.","30쪽이에요.","소이의 다짐."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#6','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C9',1,'mc','auto','병에 걸리지 않도록 미리 막는 것을 뜻하는 낱말은?',ARRAY['K2-2-u1-X16']::text[],false,'{"seq":6,"concept":"K2-2-u1-C9","difficulty":1,"kind":"mc","stem":"병에 걸리지 않도록 미리 막는 것을 뜻하는 낱말은?","options":[{"t":"예방","correct":true},{"t":"얘방","mis":"K2-2-u1-X16"},{"t":"애방","mis":"K2-2-u1-X16"}],"explanation":["예방이에요.","ㅖ가 들어가요.","38쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#7','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C5',1,'mc','auto','「서로」를 읽고 든 느낌으로 알맞은 것은?',ARRAY['K2-2-u1-X05','K2-2-u1-X07']::text[],false,'{"seq":7,"concept":"K2-2-u1-C5","difficulty":1,"kind":"mc","stem":"「서로」를 읽고 든 느낌으로 알맞은 것은?","options":[{"t":"서로 아끼는 마음이 따뜻하게 느껴져요","correct":true},{"t":"꽃들이 서로 싸워서 무서워요","mis":"K2-2-u1-X05"},{"t":"나는 오늘 수학을 공부했어요","mis":"K2-2-u1-X07"}],"explanation":["서로 걱정하는 마음이에요.","36쪽이에요.","장면과 이어요."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#8','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C2',1,'mc','auto','친구가 이야기를 소개할 때 듣는 사람이 할 일은?',ARRAY['K2-2-u1-X09']::text[],false,'{"seq":8,"concept":"K2-2-u1-C2","difficulty":1,"kind":"mc","stem":"친구가 이야기를 소개할 때 듣는 사람이 할 일은?","options":[{"t":"궁금한 점을 물어봐요","correct":true},{"t":"딴짓을 해요","mis":"K2-2-u1-X09"},{"t":"다른 이야기를 해요","mis":"K2-2-u1-X09"}],"explanation":["궁금한 점을 물어요.","9쪽 3번이에요.","능동적으로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#9','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C3',2,'mc','auto','「‘궁시렁궁시렁’이라는 표현을 보고 물건들이 불만을 드러내는 장면을 상상했어.」 — 어떤 방법인가요?',ARRAY['K2-2-u1-X03']::text[],false,'{"seq":9,"concept":"K2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「‘궁시렁궁시렁’이라는 표현을 보고 물건들이 불만을 드러내는 장면을 상상했어.」 — 어떤 방법인가요?","options":[{"t":"인상 깊은 표현을 생각하며","correct":true},{"t":"자신의 경험과 비교하며","mis":"K2-2-u1-X03"},{"t":"내용을 떠올리며","mis":"K2-2-u1-X03"}],"explanation":["표현에 주목.","국어활동 9쪽이에요.","세 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#10','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C5',2,'mc','auto','「서로」에 대한 생각이나 느낌으로 알맞은 것은?',ARRAY['K2-2-u1-X07']::text[],false,'{"seq":10,"concept":"K2-2-u1-C5","difficulty":2,"kind":"mc","stem":"「서로」에 대한 생각이나 느낌으로 알맞은 것은?","options":[{"t":"키 작은 꽃과 키 큰 꽃이 서로 걱정해 주는 모습이 다정해","correct":true},{"t":"꽃 이름은 어려워","mis":"K2-2-u1-X07"},{"t":"나는 비 오는 날이 싫어","mis":"K2-2-u1-X07"}],"explanation":["시의 장면과 이어요.","36쪽이에요.","상관없는 말은 아니에요."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#11','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C7',2,'mc','auto','「콩쥐팥쥐」에서 두꺼비가 물독을 막아 주었을 때 콩쥐의 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":11,"concept":"K2-2-u1-C7","difficulty":2,"kind":"mc","stem":"「콩쥐팥쥐」에서 두꺼비가 물독을 막아 주었을 때 콩쥐의 마음은?","options":[{"t":"고마운 마음","correct":true},{"t":"화난 마음","mis":"K2-2-u1-X12"},{"t":"귀찮은 마음","mis":"K2-2-u1-X12"}],"explanation":["도움을 받았어요.","7쪽이에요.","상황이 근거."],"asset":{"type":"speech","turns":[{"who":"이야기 속 두꺼비","text":"콩쥐야, 내가 물독의 깨진 부분을 막아 줄 테니 걱정하지 마."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#12','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C9',2,'match','auto','문장과 빈칸에 들어갈 낱말을 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-2-u1-C9","difficulty":2,"kind":"match","stem":"문장과 빈칸에 들어갈 낱말을 이어 보세요.","pairs":[{"l":"(  ) 지켜보던 소이","r":"곰곰이"},{"l":"왜 (  ) 의자를 가지고 나왔어요?","r":"멀쩡한"},{"l":"(  ) 찾을 수가 없어서 왔단다","r":"도무지"}],"mis":"K2-2-u1-X15","explanation":["문맥에 맞게.","31쪽 예시 답안이에요.","넣어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#13','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C4',2,'ox','auto','「짜장 요일」의 「짜장 수염」은 아이에게 진짜 수염이 났다는 뜻이에요.',ARRAY['K2-2-u1-X06']::text[],false,'{"seq":13,"concept":"K2-2-u1-C4","difficulty":2,"kind":"ox","stem":"「짜장 요일」의 「짜장 수염」은 아이에게 진짜 수염이 났다는 뜻이에요.","answer":"X","reason_options":[{"t":"짜장 양념이 수염처럼 묻은 모습을 빗댄 말이니까","correct":true},{"t":"시에 나온 말은 모두 글자 그대로니까","mis":"K2-2-u1-X06"}],"mis":"K2-2-u1-X06","explanation":["빗댄 말이에요.","15쪽이에요.","「~처럼」 넣어 풀어요."],"asset":{"type":"scene","icon":"🍜🧒🧒","text":"『국어』 14~15쪽 「짜장 요일」(방주현) — 급식으로 나온 짜장면을 먹으며 얼굴에 짜장이 묻은 아이들을 노래한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#14','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C6',2,'mc','auto','「엉뚱한 수리점」에서 깜깜한 밤이 된 뒤에 일어난 일은?',ARRAY['K2-2-u1-X10']::text[],false,'{"seq":14,"concept":"K2-2-u1-C6","difficulty":2,"kind":"mc","stem":"「엉뚱한 수리점」에서 깜깜한 밤이 된 뒤에 일어난 일은?","options":[{"t":"수리점에 불이 켜지고 어른들이 줄을 섰다","correct":true},{"t":"소이와 친구들이 숨바꼭질을 시작했다","mis":"K2-2-u1-X10"},{"t":"산들바람이 불기 시작했다","mis":"K2-2-u1-X10"}],"explanation":["밤 → 줄.","27쪽이에요.","차례를 생각해요."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#15','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C8',2,'mc','auto','소이에 대한 생각으로 알맞은 것은?',ARRAY['K2-2-u1-X14']::text[],false,'{"seq":15,"concept":"K2-2-u1-C8","difficulty":2,"kind":"mc","stem":"소이에 대한 생각으로 알맞은 것은?","options":[{"t":"물건의 좋은 점을 찾아내는 지혜로운 아이 같아","correct":true},{"t":"소이는 물건을 잘 고치는 기술자 같아","mis":"K2-2-u1-X14"},{"t":"소이는 밤에 잠만 자는 아이 같아","mis":"K2-2-u1-X14"}],"explanation":["인물의 말이 근거.","지도서 79쪽 편지예요.","인물의 모습."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
