INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#17','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C3',3,'error','auto','한 친구가 「내 그림이 친구와 다르니 내 그림은 틀렸어.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X04']::text[],false,'{"seq":17,"concept":"K2-2-u1-C3","difficulty":3,"kind":"error","stem":"한 친구가 「내 그림이 친구와 다르니 내 그림은 틀렸어.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"시의 말을 근거로 그렸다면 친구와 달라도 괜찮아요","correct":true,"mis_target":"K2-2-u1-X04"},{"t":"잘 말했어요","mis":"K2-2-u1-X04"},{"t":"친구 그림을 따라 그려야 해요","mis":"K2-2-u1-X04"}],"explanation":["다를 수 있어요.","지도서 62~63쪽이에요.","근거를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
