INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#20','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C7',3,'mc','auto','소이가 「난 절대 고치지 않을 거야.」라고 생각한 마음은?',ARRAY['K2-2-u1-X12']::text[],false,'{"seq":20,"concept":"K2-2-u1-C7","difficulty":3,"kind":"mc","stem":"소이가 「난 절대 고치지 않을 거야.」라고 생각한 마음은?","options":[{"t":"재미있는 것을 지키고 싶은 마음","correct":true},{"t":"물건을 빨리 버리고 싶은 마음","mis":"K2-2-u1-X12"},{"t":"수리점 아저씨가 고마운 마음","mis":"K2-2-u1-X12"}],"explanation":["재미없게 만들까 봐요.","30쪽이에요.","말이 근거."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
