INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#22','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C4',3,'error','auto','한 친구가 「「서로」에서 두 꽃은 뜨거운 햇볕 때문에 걱정했어.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u1-X05']::text[],false,'{"seq":22,"concept":"K2-2-u1-C4","difficulty":3,"kind":"error","stem":"한 친구가 「「서로」에서 두 꽃은 뜨거운 햇볕 때문에 걱정했어.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"세찬 비 때문에 서로를 걱정했어요","correct":true,"mis_target":"K2-2-u1-X05"},{"t":"잘 말했어요","mis":"K2-2-u1-X05"},{"t":"눈 때문이라고 해야 해요","mis":"K2-2-u1-X05"}],"explanation":["비 때문이에요.","36쪽이에요.","시를 다시 읽어요."],"asset":{"type":"scene","icon":"🌧️🌼🌻","text":"『국어』 36쪽 「서로」(조영수) — 세찬 비가 내린 밤, 채송화와 해바라기가 서로를 걱정한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#23','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C9',4,'sa','auto','「흠이 없이 온전한」이라는 뜻의 낱말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u1-C9","difficulty":4,"kind":"sa","stem":"「흠이 없이 온전한」이라는 뜻의 낱말을 쓰세요.","answer":["멀쩡한","멀쩡하다"],"explanation":["멀쩡한이에요.","31쪽이에요.","넣어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#24','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C8',4,'essay','teacher','「엉뚱한 수리점」을 읽고 소이에게 하고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u1-C8","difficulty":4,"kind":"essay","stem":"「엉뚱한 수리점」을 읽고 소이에게 하고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 소이야, 고장 난 것 같은 물건에서도 재미있는 점을 찾아내는 네가 멋져. 나도 내 물건의 좋은 점을 찾아볼게. — 소이가 한 일과 이어진 말이면 맞아요.","scoring_points":["소이에게 말하듯 썼는가","소이가 한 일과 이어졌는가","생각이나 느낌이 있는가"]},"explanation":["인물에게 하고 싶은 말.","국어활동 10~25쪽이에요.","문장으로."],"asset":{"type":"passage","lines":["소이와 친구들은 광장 분수대에서 날이 어두워지는 줄도 모르고 놀았어요.","깜깜한 밤, 엉뚱한 수리점 앞에 어른들이 고칠 물건을 들고 줄을 섰어요.","소이 눈에는 그 물건들이 고장 난 것처럼 보이지 않았어요.","삐거덕 의자도, 넣으면 못 찾는 옷장도, 강아지풀 화분도","소이에게는 재미있는 물건이었어요.","소이는 빗자루를 새처럼 날게 고쳐 달라고 했지만,","아저씨는 청소용으로 튼튼하게만 고칠 수 있다고 했어요.","소이는 집으로 돌아와 「난 절대 고치지 않을 거야.」 하고 생각했어요."],"title":"「엉뚱한 수리점」(차재혁) 간추림 — 『국어』 26~30쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u1_review_d#25','kor',2,2,'u1','','g2_2_kor_u1_review_d','unit_review','K2-2-u1-C2',4,'essay','teacher','친구가 소개한 이야기를 듣고 궁금한 점 두 가지를 질문으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u1-C2","difficulty":4,"kind":"essay","stem":"친구가 소개한 이야기를 듣고 궁금한 점 두 가지를 질문으로 쓰세요.","answer_guide":{"answer":"예: 그다음에 어떤 일이 일어났어? / 주인공은 어떻게 됐어? — 이야기 내용과 관련된 질문이 두 개 있으면 맞아요.","scoring_points":["질문이 두 개인가","이야기 내용과 관련 있는가","묻는 문장으로 썼는가"]},"explanation":["이야기 내용을 물어요.","지도서 59쪽 예시 질문이에요.","두 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
